/* ======== [已给出] 模块 11 freeList ======== */

void freeList(LinkList *L)
{
    LNode *p = (*L)->next;
    LNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}

