modes.detail:
// ============ 遍历的固定套路 ============
//
//   p = L->next;              ← 跳过不存数据的头结点
//   while (p != NULL) {       ← 走到 NULL 说明到尾了
//       ... 处理 p->data ...
//       p = p->next;          ← 千万别忘了这一句，否则死循环
//   }
//
// 输出格式 10 -> 20 -> 30 -> NULL，最后那个 NULL 是"链尾"的可视化，
// 方便一眼看出链表在哪里结束。

// 只读操作，不需要修改链表，参数直接传 LinkList（一级指针）
void printList(LinkList L)
{
// 从第一个真实结点开始
    LNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，"->" 是链表的视觉箭头
        printf("%d -> ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}

