modes.detail:
// ============ 测试程序的编排思路 ============
// 千万不要一次性把所有操作写完再运行，那样出错无从下手。
// 正确做法是"一步一打印"：每做完一个操作就 printList，
// 让输出自己告诉你哪一步开始不对。
//
// 另外一定要测三种边界：
//   1. 空表      （初始化后立刻打印）
//   2. 越界位置  （插入/查找/删除一个不存在的位置，应返回 ERROR）
//   3. 空表释放  （防止 freeList 对空表崩溃）

// 主函数不需要参数，返回 0 表示正常结束
int main(void)
{
// L 是头结点指针，先置 NULL，等 InitList 去创建头结点
    LinkList L = NULL;
// p 用来接 LocateElem 返回的结点地址
    LNode *p = NULL;
// e 用来接按位查找 / 删除带回来的数据
    ElemType e = 0;

// ========== 第 1 步：初始化 ==========
    printf("========== 1. 初始化 ==========\n");
// 检查返回值，初始化失败就没必要继续了
    if (InitList(&L) != OK)
    {
// 失败提示
        printf("初始化失败！\n");
// 直接返回错误码
        return ERROR;
    }
// 打印验证：此时应该是空表
    printf("初始化完成，当前链表：");
    printList(L);

// ========== 第 2 步：尾部追加 ==========
    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
// 依次追加三个数
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
// 期望输出：10 -> 20 -> 30 -> NULL
    printf("追加后：");
    printList(L);

// ========== 第 3 步：头插法 ==========
    printf("\n========== 3. 头插法插入 ==========\n");
// 头插 5：不遍历，直接变成第 1 个结点
    HeadInsert(L, 5);
// 期望输出：5 -> 10 -> 20 -> 30 -> NULL
    printf("头插后：");
    printList(L);

// 再头插 3，亲眼看一次"头插会颠倒顺序"
    HeadInsert(L, 3);
// 期望输出：3 -> 5 -> 10 -> 20 -> 30 -> NULL
// 头插法建出来的表天生是逆序的，所以"头插法建表"常被拿来倒序一个数组
    printf("再头插 3 后：");
    printList(L);

// ========== 第 4 步：按位插入 ==========
    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
// 插到第 2 个位置，即 3 和 5 之间
    ListInsert(L, 2, 15);
// 期望输出：3 -> 15 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("插入后：");
    printList(L);

// 越界测试：在第 99 位插入必须失败
    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 5 步：按位查找 ==========
    printf("\n========== 5. 按位查找 ==========\n");
// 查第 3 个元素，用 e 带回结果
// 此时链表是 3 -> 15 -> 5 -> 10 -> 20 -> 30，第 3 个是 5
    if (GetElem_L(L, 3, &e) == OK)
    {
// 期望输出：5
        printf("第 3 个元素的值是 %d\n", e);
    }
// 越界查找测试
    if (GetElem_L(L, 100, &e) == ERROR)
    {
// 期望走到这里
