/* ======== [已给出] 模块 01 头文件与 typedef ======== */

#include <stdio.h>
#include <stdlib.h>

#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

typedef int Status;
typedef int ElemType;

typedef struct LNode {
    ElemType data;
    struct LNode *next;
} LNode, *LinkList;

/* ======== [已给出] 模块 02 creatNode ======== */

LNode *creatNode(ElemType e)
{
    LNode *p = (LNode *)malloc(sizeof(LNode));

    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
        exit(OVERFLOW);
    }

    p->data = e;
    p->next = NULL;

    return p;
}

/* ======== [已给出] 模块 03 InitList ======== */

Status InitList(LinkList *L)
{
    *L = (LinkList)malloc(sizeof(LNode));
    if (*L == NULL) return ERROR;
    (*L)->next = NULL;
    return OK;
}

/* ======== [已给出] 模块 04 applist ======== */

Status applist(LinkList L, ElemType e)
{
    LNode *p = L;
    LNode *s = NULL;

    if (L == NULL) return ERROR;

    while (p->next != NULL)
    {
        p = p->next;
    }

    s = creatNode(e);

    p->next = s;

    return OK;
}

/* ======== [已给出] 模块 05 HeadInsert ======== */

Status HeadInsert(LinkList L, ElemType e)
{
    LNode *s = NULL;

    if (L == NULL) return ERROR;

    s = creatNode(e);

    s->next = L->next;
    L->next = s;

    return OK;
}

/* ======== [已给出] 模块 06 GetElem_L ======== */

Status GetElem_L(LinkList L, int i, ElemType *e)
{
    LNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    return OK;
}

/* ======== [已给出] 模块 07 LocateElem ======== */

LNode *LocateElem(LinkList L, ElemType e)
{
    LNode *p = L->next;

    while (p != NULL && p->data != e)
    {
        p = p->next;
    }

    return p;
}

/* ======== [已给出] 模块 08 ListInsert ======== */

Status ListInsert(LinkList L, int i, ElemType e)
{
    LNode *p = L;
    LNode *s = NULL;
    int j = 0;

    while (p != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i - 1) return ERROR;

    s = creatNode(e);

    s->next = p->next;
    p->next = s;

    return OK;
}

/* ======== [已给出] 模块 09 ListDelete ======== */

Status ListDelete(LinkList L, int i, ElemType *e)
{
    LNode *p = L;
    LNode *q = NULL;
    int j = 0;

    while (p->next != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p->next == NULL || j > i - 1) return ERROR;

    q = p->next;
    *e = q->data;
    p->next = q->next;
    free(q);

    return OK;
}

/* ======== [已给出] 模块 10 printList ======== */

void printList(LinkList L)
{
    LNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p != NULL)
    {
        printf("%d -> ", p->data);
        p = p->next;
    }

    printf("NULL\n");
}

/* ======== [已给出] 模块 11 freeList ======== */

void freeList(LinkList *L)
{
    LNode *p = (*L)->next;
    LNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}

/* ====================================================================
 *  轮到你了：模块 12  main
 *  作用：把 9 个基本操作串起来跑一遍，用输出验证每一步的结果是否符合预期。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */

modes.detail:
// ============ 为什么要 typedef ============
// C 语言里 struct LNode 必须连在一起写，typedef 之后：
//     LNode     等价于  struct LNode
//     LinkList  等价于  struct LNode *
// 从此代码里只出现 LNode / LinkList，可读性大幅提升。
// 注意 LinkList 是"指针类型"，所以 LinkList L 本身就是一个指针变量。

// 标准输入输出，printf 需要
#include <stdio.h>
// 内存管理，malloc / free 需要
#include <stdlib.h>

// 用宏定义状态码，让函数返回值有意义（比裸 1 / 0 好读）
// 约定：函数返回 Status，OK 表示成功，ERROR 表示失败。
#define OK 1
// #define 是预处理指令，编译前做文本替换：代码里 OK 直接变成 1
#define ERROR 0
// 布尔值宏，教材习惯写法
#define TRUE 1
#define FALSE 0
// 内存分配失败的专用错误码，取一个和 OK/ERROR 都不冲突的负数
#define OVERFLOW -2

// Status 是函数返回类型；ElemType 是数据域类型
// 把 int 换成 float / char，整份代码不用改，这就是 typedef 的价值
typedef int Status;
typedef int ElemType;

// 结点结构体：数据域 data + 指针域 next
// ============ 内存里长什么样 ============
//
//   头结点(不存数据)        第 1 个结点          第 2 个结点
//   ┌────┬──────┐      ┌────┬──────┐      ┌────┬──────┐
//   │ -- │ next │─────▶│ 10 │ next │─────▶│ 20 │ NULL │
//   └────┴──────┘      └────┴──────┘      └────┴──────┘
//      L                 L->next            带数据的第一颗
//
// 头结点是"哨兵"：它不存有效数据，只为让插入/删除不用特判第一个位置。
typedef struct LNode {
// 数据域，存具体元素
    ElemType data;
// 指针域，指向下一个结点；最后一个结点为 NULL
// struct LNode *next 不能写成 LNode *next —— 此时 LNode 这个名字还没生效
    struct LNode *next;
// 一次 typedef 出两个名字：LNode（结点）和 LinkList（指向结点的指针）
} LNode, *LinkList;

// ============ 这个函数是后面所有插入操作的地基 ============
// 任何"插入"最终都要先造出一个新结点，思路永远是：
//   申请内存 → 填数据 → 指针域置 NULL → 把地址交出去
// 内存申请必须检查失败！malloc 失败返回 NULL，直接解引用会崩溃。

// 返回新结点的地址，所以返回类型是 LNode *
// 参数 e 按值传递：函数内改 e 不影响调用者，因为我们只需要它的值
LNode *creatNode(ElemType e)
{
// 申请一个结点大小的内存，强制转换成 LNode *
// sizeof(LNode) 通常等于 8（int 4 字节 + 指针 4 字节）或 16（64 位下指针 8 字节）
    LNode *p = (LNode *)malloc(sizeof(LNode));

// 申请失败必须拦住，否则后面 p->data 就是非法访问
    if (p == NULL)
    {
// printf 打印中文提示，让使用者知道是内存不够，而不是程序莫名其妙退出
        printf("内存分配失败：无法创建新结点。\n");
// 申请不到内存属于致命错误，直接结束程序
        exit(OVERFLOW);
    }

// 填数据域
    p->data = e;
// 新结点的 next 必须先置 NULL，否则它是野指针
// 这是最容易漏的一步：漏了之后链表尾部就不"封口"，遍历会冲到非法内存
    p->next = NULL;

// 把新结点的地址返回给调用者
    return p;
}

// ============ 为什么需要"头结点" ============
// 没有头结点时，在第一个位置插入/删除都要单独写一段代码；
// 有了头结点，第一个位置和中间位置的操作逻辑完全一样，代码短一半。
//
//   初始化完成后：   L ──▶ ┌────┬──────┐
//                          │ -- │ NULL │
//                          └────┴──────┘

// 参数是 LinkList *（二级指针），因为要修改调用者手里的 L 本身
// 如果写成 LinkList L，函数内改了 L 也传不回去，调用者的 L 还是野指针
Status InitList(LinkList *L)
{
// 只申请头结点，不存数据
    *L = (LinkList)malloc(sizeof(LNode));
// 头结点也可能申请失败
    if (*L == NULL) return ERROR;
// 空表的标志：头结点的 next 为 NULL
    (*L)->next = NULL;
// 返回 OK 表示初始化成功
    return OK;
}

// ============ 指针推进过程 ============
// 目标：在尾部追加 30
//
//  初始：  L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ NULL
//          p
//
//  循环：  L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ NULL
//                              p        （p->next != NULL，继续走）
//
//  停止：  L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ NULL
//                                     p   （p->next == NULL，p 就是尾结点）
//
//  挂上：  L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ [30] ─▶ NULL
// 关键：p 从头结点起步，不是从 L->next 起步 —— 这样空表也能正确处理。

// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
// 返回值用 Status，让调用者知道追加成功与否
Status applist(LinkList L, ElemType e)
{
// p 是"游标"，从头结点开始；它最终会停在尾结点上
    LNode *p = L;
// s 用来接住 creatNode 造出来的新结点
    LNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 一路向后走，直到 p 后面没有结点了
// 循环条件是 p->next != NULL，看的永远是"下一个"，所以停下时 p 正是尾结点
    while (p->next != NULL)
    {
// 指针后移一格
        p = p->next;
    }

// 造新结点，地址交给 s
    s = creatNode(e);

// 把新结点接到尾结点后面，链表就延长了一节
// 只需要改一处指针；原来的尾结点 next 从 NULL 变成指向 s
    p->next = s;

// 返回 OK 表示追加成功
    return OK;
}

// ============ 头插法 vs 尾插法 ============
//
//   applist（尾插）  ：从头一路走到尾，找到尾结点再挂上    —— 时间复杂度 O(n)
//   HeadInsert（头插）：直接插在头结点后面，碰都不碰其他结点 —— 时间复杂度 O(1)
//
// 代价是头插会**颠倒顺序**：依次头插 10、20、30，得到的是 30 -> 20 -> 10。
// 这不是缺陷，恰恰是头插法最常用的一个特性 —— "头插法建表"就是靠它做逆序的：
//
//     LinkList L;
//     InitList(&L);
//     for (i = 0; i < n; i++)
//     {
//         HeadInsert(L, a[i]);     /* 建出来的表正好是数组 a 的逆序 */
//     }
//
// 再记住一个等价关系：HeadInsert(L, e) 和 ListInsert(L, 1, e) 干的是同一件事，
// 前者只是把"找第 0 个结点"这一步省掉了 —— 因为头结点本身就是第 0 个。
//
// ============ 两步指针操作，顺序不能反 ============
// 目标：把 5 头插进 10 -> 20 -> 30
//
//  插入前：   L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ [30] ─▶ NULL
//
//  第一步（新结点先接住原来的头一个）：s->next = L->next
//            L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ [30] ─▶ NULL
//                          ▲
//            [5] ──────────┘
//             s
//
//  第二步（头结点再指向新结点）：L->next = s
//            L ─▶ [头] ─▶ [5] ─▶ [10] ─▶ [20] ─▶ [30] ─▶ NULL
//                          s
//
// 头结点 [头] 本身始终待在原地，头插法动的只是它的 next 指针。

// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
// 位置固定是第 1 位，所以不像 ListInsert 那样需要 i 这个参数
Status HeadInsert(LinkList L, ElemType e)
{
// s 是等待挂链的新结点
    LNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点先接住原来头结点后面的那一串
// 做完这一步，链表本身还是完整的，只是多了一个"悬挂"在外面的 s
    s->next = L->next;
// 第二步：头结点再指向新结点，s 正式成为第 1 个结点
// 顺序同样不能反！先执行 L->next = s 的话，原来第一个结点的地址就丢了（内存泄漏）
    L->next = s;

// 插入成功
    return OK;
}

// ============ 找第 3 个结点（i = 3）============
//
//   L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ [30] ─▶ NULL
//          j=1     j=2     j=3
//           p       p       p
//
//  循环结束时 j == i，p 正好停在第 i 个结点上。
// 两个必须同时检查的失败情况：
//   p == NULL  → i 比表长还大，数着数着掉出去了
//   j > i      → i 小于 1（比如 i = 0），循环一次都没进

// 结果通过 e 带回去，所以要传 ElemType *（地址），不是 ElemType
// 这是 C 语言"函数只能返回一个值"的经典绕法：返回值给状态，数据走指针参数
Status GetElem_L(LinkList L, int i, ElemType *e)
{
// 从第 1 个"带数据的结点"开始，所以是 L->next 而不是 L
// 头结点不存数据，跳过它 —— 这是带头结点链表里最常见的起点写法
    LNode *p = L->next;
// 计数器 j 与 p 同步，表示"p 现在指的是第几个结点"
    int j = 1;

// 边走边数，直到数到 i 或者走到表尾
// p != NULL 写在前面，短路求值保证不会对空指针取 ->next
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步加一
        j++;
    }

// 越界检查：p 为空说明 i 超过表长；j > i 说明 i 小于 1
    if (p == NULL || j > i) return ERROR;

// 把找到的数据写到调用者提供的地址里
    *e = p->data;

// 查找成功
    return OK;
}

// ============ 按值查找和按位查找的区别 ============
// 按位查找：数位置，返回"值"
// 按值查找：比值，返回"结点地址"
//
// 为什么返回地址而不是值？因为拿回地址后，调用者还能继续访问
// p->next 等后继信息，也可以在它前面做插入删除。
//
// 找不到时返回 NULL —— C 语言里表示"没有这个结点"的标准做法。

// 返回 LNode *，找不到就是 NULL
LNode *LocateElem(LinkList L, ElemType e)
{
// 同样从第一个带数据的结点开始
    LNode *p = L->next;

// 两个条件：还没走到尾，且当前值不等于目标
// 一旦 p->data == e，循环立刻停下，p 就停在第一个匹配的结点上
    while (p != NULL && p->data != e)
    {
// 不匹配就继续往后
        p = p->next;
    }

// 找到返回地址，没找到时 p 已经是 NULL，直接返回即可
    return p;
}

// ============ 插入的核心：两句指针赋值不能写反 ============
// 目标：在第 2 个位置插入 15
//
//  插入前：  L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ NULL
//                       p
//
//  第一步（先接后面）：s->next = p->next
//          [15] ─────▶ [20]
//            s           ▲
//                        └── 此时 p->next 还指着 [20]
//
//  第二步（再断前面）：p->next = s
//          [10] ─▶ [15] ─▶ [20]
//            p       s
//
// 如果两句写反，先执行 p->next = s，[20] 的地址就丢了（内存泄漏），
// 而且 s->next 会指向 s 自己，链表出现环 —— 这是最经典的踩坑点。
//
// 还有一条铁律：先判断能不能插，再造结点。顺序颠倒会导致插入失败时
// 白白多出一个没挂上链表的"孤儿结点"。

// 参数 L 是头结点指针（不需要改 L 本身）；i 是位置，e 是数据
// 位置 i 从 1 开始计数，表示"插完以后它是第 i 个结点"
Status ListInsert(LinkList L, int i, ElemType e)
{
// p 要从头结点开始：因为插到第 1 位时，前驱就是头结点
// 这正是头结点的价值 —— 第 1 位和后面位置走同一段逻辑
    LNode *p = L;
// s 是等待挂链的新结点
    LNode *s = NULL;
// j 表示 p 当前指向第几个结点；头结点算第 0 个
    int j = 0;

// 走 i-1 步，让 p 停在"第 i 个结点的前驱"上
// 循环条件 j < i - 1：i = 1 时一次也不进循环，p 直接就是头结点
    while (p != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 合法性检查：p 为空说明 i-1 已经超过表长；j > i-1 说明 i < 1
// 注意这里是先检查后造结点，避免产生孤儿结点
    if (p == NULL || j > i - 1) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点先接住后面的那一串（顺序不能反！）
    s->next = p->next;
// 第二步：前驱再指向新结点，链表正式接上
    p->next = s;

// 返回 OK 表示插入成功
    return OK;
}

// ============ 删除的三步 ============
// 目标：删除第 2 个结点（值为 15）
//
//  删除前：  L ─▶ [头] ─▶ [10] ─▶ [15] ─▶ [20] ─▶ NULL
//                       p        q
//
//  摘链：    p->next = q->next    把 [20] 的地址交给 p
//           L ─▶ [头] ─▶ [10] ─▶ [20] ─▶ NULL
//                       p        q（已被绕开，但还占着内存）
//
//  释放：    free(q)             把结点还给系统，q 变野指针
//
// 顺序要点：一定要先把 q->data 存进 *e，再 free(q)；
// 一旦 free 之后再去读 q->data 就是"释放后使用"，属于未定义行为。
// 另外 free 之后建议把 q 置 NULL，防止后续误用。

// 删除的数据要通过 *e 带出去
Status ListDelete(LinkList L, int i, ElemType *e)
{
// p 从头结点起步，最终停在第 i-1 个结点
    LNode *p = L;
// q 是被摘下来的那个结点
    LNode *q = NULL;
// j 记录 p 的位置，头结点记为 0
    int j = 0;

// 走 i-1 步定位前驱
// 这里用 p->next != NULL 作为条件：确保 p 后面确实有一个结点可以摘
    while (p->next != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：p->next 为空说明第 i 个结点不存在
    if (p->next == NULL || j > i - 1) return ERROR;

// 用 q 记住待删结点
    q = p->next;
// 先把数据取出来交给调用者（必须在 free 之前做）
    *e = q->data;
// 摘链：前驱直接跨过 q，指向 q 的后继
    p->next = q->next;
// 释放 q 占用的内存，防止内存泄漏
    free(q);

// 删除成功
    return OK;
}

// ============ 遍历的固定套路 ============
//
//   p = L->next;              ← 跳过不存数据的头结点
//   while (p != NULL) {       ← 走到 NULL 说明到尾了
//       ... 处理 p->data ...
//       p = p->next;          ← 千万别忘了这一句，否则死循环
//   }
//
// 输出格式 10 -> 20 -> 30 -> NULL，最后那个 NULL 是"链尾"的可视化，
// 方便一眼看出链表在哪里结束。

// 只读操作，不需要修改链表，参数直接传 LinkList（一级指针）
void printList(LinkList L)
{
// 从第一个真实结点开始
    LNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，"->" 是链表的视觉箭头
        printf("%d -> ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}

// ============ 为什么必须先保存 next ============
//
//  错误写法：                正确写法：
//    free(p);                  q = p;
//    p = p->next;   ← 危险!    p = p->next;
//                             free(q);
//
// free(p) 之后那块内存已经还给系统，p->next 读到的是垃圾值，
// 用这个垃圾值当地址去访问就是"释放后使用"（use after free）。
// 所以要先记住后继，再释放当前。

// 参数是 LinkList *，因为最后要把调用者的 L 改成 NULL
// 如果传一级指针，函数内把 L 置 NULL 传不回去，调用者手里就是野指针
void freeList(LinkList *L)
{
// 从第一个真实结点开始清理
    LNode *p = (*L)->next;
// q 用来暂存"即将被释放"的那个结点
    LNode *q = NULL;

// 逐个结点释放
    while (p != NULL)
    {
// 先记住当前结点
        q = p;
// 再让 p 走到下一个（此时 p 已经安全了）
        p = p->next;
// 最后才释放 q
// 这三步顺序固定：存 → 走 → 放，缺一不可
        free(q);
    }

// 数据结点都清完了，头结点也要还回去
    free(*L);
// 把调用者的指针置 NULL，避免它继续指向已释放的内存
    *L = NULL;
}

// ============ 测试程序的编排思路 ============
// 千万不要一次性把所有操作写完再运行，那样出错无从下手。
// 正确做法是"一步一打印"：每做完一个操作就 printList，
// 让输出自己告诉你哪一步开始不对。
//
// 另外一定要测三种边界：
//   1. 空表      （初始化后立刻打印）
//   2. 越界位置  （插入/查找/删除一个不存在的位置，应返回 ERROR）
//   3. 空表释放  （防止 freeList 对空表崩溃）

// 主函数不需要参数，返回 0 表示正常结束
int main(void)
{
// L 是头结点指针，先置 NULL，等 InitList 去创建头结点
    LinkList L = NULL;
// p 用来接 LocateElem 返回的结点地址
    LNode *p = NULL;
// e 用来接按位查找 / 删除带回来的数据
    ElemType e = 0;

// ========== 第 1 步：初始化 ==========
    printf("========== 1. 初始化 ==========\n");
// 检查返回值，初始化失败就没必要继续了
    if (InitList(&L) != OK)
    {
// 失败提示
        printf("初始化失败！\n");
// 直接返回错误码
        return ERROR;
    }
// 打印验证：此时应该是空表
    printf("初始化完成，当前链表：");
    printList(L);

// ========== 第 2 步：尾部追加 ==========
    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
// 依次追加三个数
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
// 期望输出：10 -> 20 -> 30 -> NULL
    printf("追加后：");
    printList(L);

// ========== 第 3 步：头插法 ==========
    printf("\n========== 3. 头插法插入 ==========\n");
// 头插 5：不遍历，直接变成第 1 个结点
    HeadInsert(L, 5);
// 期望输出：5 -> 10 -> 20 -> 30 -> NULL
    printf("头插后：");
    printList(L);

// 再头插 3，亲眼看一次"头插会颠倒顺序"
    HeadInsert(L, 3);
// 期望输出：3 -> 5 -> 10 -> 20 -> 30 -> NULL
// 头插法建出来的表天生是逆序的，所以"头插法建表"常被拿来倒序一个数组
    printf("再头插 3 后：");
    printList(L);

// ========== 第 4 步：按位插入 ==========
    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
// 插到第 2 个位置，即 3 和 5 之间
    ListInsert(L, 2, 15);
// 期望输出：3 -> 15 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("插入后：");
    printList(L);

// 越界测试：在第 99 位插入必须失败
    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 5 步：按位查找 ==========
    printf("\n========== 5. 按位查找 ==========\n");
// 查第 3 个元素，用 e 带回结果
// 此时链表是 3 -> 15 -> 5 -> 10 -> 20 -> 30，第 3 个是 5
    if (GetElem_L(L, 3, &e) == OK)
    {
// 期望输出：5
        printf("第 3 个元素的值是 %d\n", e);
    }
// 越界查找测试
    if (GetElem_L(L, 100, &e) == ERROR)
    {
// 期望走到这里
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

// ========== 第 6 步：按值查找 ==========
    printf("\n========== 6. 按值查找 ==========\n");
// 找值为 20 的结点
    p = LocateElem(L, 20);
// 找到就打印它的后继信息
    if (p != NULL)
    {
// p->next 非空则说明 20 不是尾结点
        printf("找到值为 20 的结点，它的后继是 %s\n", p->next != NULL ? "一个有效结点" : "NULL");
    }
// 找不存在的值应当返回 NULL
    if (LocateElem(L, 99) == NULL)
    {
// 期望走到这里
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

// ========== 第 7 步：按位删除 ==========
    printf("\n========== 7. 删除第 1 个结点 ==========\n");
// 删除第 1 个结点，被删的值通过 e 带出来
    if (ListDelete(L, 1, &e) == OK)
    {
// 期望输出：被删除的是 3
        printf("已删除第 1 个结点，它的值是 %d\n", e);
    }
// 期望输出：15 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("删除后：");
    printList(L);

// 越界删除测试
    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 8 步：释放整表 ==========
    printf("\n========== 8. 释放内存 ==========\n");
// 释放所有结点，并把 L 置为 NULL
    freeList(&L);
// 期望输出：NULL，证明 L 已被正确置空
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

// 正常结束
    return 0;
}

modes.short:
// 标准输入输出，printf 需要
#include <stdio.h>
// 内存管理，malloc / free 需要
#include <stdlib.h>

// 用宏定义状态码，让函数返回值有意义（比裸 1 / 0 好读）
#define OK 1
#define ERROR 0
// 布尔值宏，教材习惯写法
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

// Status 是函数返回类型；ElemType 是数据域类型
typedef int Status;
typedef int ElemType;

// 结点结构体：数据域 data + 指针域 next
typedef struct LNode {
// 数据域，存具体元素
    ElemType data;
// 指针域，指向下一个结点；最后一个结点为 NULL
    struct LNode *next;
// 一次 typedef 出两个名字：LNode（结点）和 LinkList（指向结点的指针）
} LNode, *LinkList;


// 返回新结点的地址，所以返回类型是 LNode *
LNode *creatNode(ElemType e)
{
// 申请一个结点大小的内存，强制转换成 LNode *
    LNode *p = (LNode *)malloc(sizeof(LNode));

// 申请失败必须拦住，否则后面 p->data 就是非法访问
    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
// 申请不到内存属于致命错误，直接结束程序
        exit(OVERFLOW);
    }

// 填数据域
    p->data = e;
// 新结点的 next 必须先置 NULL，否则它是野指针
    p->next = NULL;

// 把新结点的地址返回给调用者
    return p;
}


// 参数是 LinkList *（二级指针），因为要修改调用者手里的 L 本身
Status InitList(LinkList *L)
{
// 只申请头结点，不存数据
    *L = (LinkList)malloc(sizeof(LNode));
// 头结点也可能申请失败
    if (*L == NULL) return ERROR;
// 空表的标志：头结点的 next 为 NULL
    (*L)->next = NULL;
// 返回 OK 表示初始化成功
    return OK;
}


// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
Status applist(LinkList L, ElemType e)
{
// p 是"游标"，从头结点开始；它最终会停在尾结点上
    LNode *p = L;
// s 用来接住 creatNode 造出来的新结点
    LNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 一路向后走，直到 p 后面没有结点了
    while (p->next != NULL)
    {
// 指针后移一格
        p = p->next;
    }

// 造新结点，地址交给 s
    s = creatNode(e);

// 把新结点接到尾结点后面，链表就延长了一节
    p->next = s;

// 返回 OK 表示追加成功
    return OK;
}


// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
Status HeadInsert(LinkList L, ElemType e)
{
// s 是等待挂链的新结点
    LNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点先接住原来头结点后面的那一串
    s->next = L->next;
// 第二步：头结点再指向新结点，s 正式成为第 1 个结点
    L->next = s;

// 插入成功
    return OK;
}


// 结果通过 e 带回去，所以要传 ElemType *（地址），不是 ElemType
Status GetElem_L(LinkList L, int i, ElemType *e)
{
// 从第 1 个"带数据的结点"开始，所以是 L->next 而不是 L
    LNode *p = L->next;
// 计数器 j 与 p 同步，表示"p 现在指的是第几个结点"
    int j = 1;

// 边走边数，直到数到 i 或者走到表尾
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步加一
        j++;
    }

// 越界检查：p 为空说明 i 超过表长；j > i 说明 i 小于 1
    if (p == NULL || j > i) return ERROR;

// 把找到的数据写到调用者提供的地址里
    *e = p->data;

// 查找成功
    return OK;
}


// 返回 LNode *，找不到就是 NULL
LNode *LocateElem(LinkList L, ElemType e)
{
// 同样从第一个带数据的结点开始
    LNode *p = L->next;

// 两个条件：还没走到尾，且当前值不等于目标
    while (p != NULL && p->data != e)
    {
// 不匹配就继续往后
        p = p->next;
    }

// 找到返回地址，没找到时 p 已经是 NULL，直接返回即可
    return p;
}


// 参数 L 是头结点指针（不需要改 L 本身）；i 是位置，e 是数据
Status ListInsert(LinkList L, int i, ElemType e)
{
// p 要从头结点开始：因为插到第 1 位时，前驱就是头结点
    LNode *p = L;
// s 是等待挂链的新结点
    LNode *s = NULL;
// j 表示 p 当前指向第几个结点；头结点算第 0 个
    int j = 0;

// 走 i-1 步，让 p 停在"第 i 个结点的前驱"上
    while (p != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 合法性检查：p 为空说明 i-1 已经超过表长；j > i-1 说明 i < 1
    if (p == NULL || j > i - 1) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点先接住后面的那一串（顺序不能反！）
    s->next = p->next;
// 第二步：前驱再指向新结点，链表正式接上
    p->next = s;

// 返回 OK 表示插入成功
    return OK;
}


// 删除的数据要通过 *e 带出去
Status ListDelete(LinkList L, int i, ElemType *e)
{
// p 从头结点起步，最终停在第 i-1 个结点
    LNode *p = L;
// q 是被摘下来的那个结点
    LNode *q = NULL;
// j 记录 p 的位置，头结点记为 0
    int j = 0;

// 走 i-1 步定位前驱
    while (p->next != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：p->next 为空说明第 i 个结点不存在
    if (p->next == NULL || j > i - 1) return ERROR;

// 用 q 记住待删结点
    q = p->next;
// 先把数据取出来交给调用者（必须在 free 之前做）
    *e = q->data;
// 摘链：前驱直接跨过 q，指向 q 的后继
    p->next = q->next;
// 释放 q 占用的内存，防止内存泄漏
    free(q);

// 删除成功
    return OK;
}


// 只读操作，不需要修改链表，参数直接传 LinkList（一级指针）
void printList(LinkList L)
{
// 从第一个真实结点开始
    LNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，"->" 是链表的视觉箭头
        printf("%d -> ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}


// 参数是 LinkList *，因为最后要把调用者的 L 改成 NULL
void freeList(LinkList *L)
{
// 从第一个真实结点开始清理
    LNode *p = (*L)->next;
// q 用来暂存"即将被释放"的那个结点
    LNode *q = NULL;

// 逐个结点释放
    while (p != NULL)
    {
// 先记住当前结点
        q = p;
// 再让 p 走到下一个（此时 p 已经安全了）
        p = p->next;
// 最后才释放 q
        free(q);
    }

// 数据结点都清完了，头结点也要还回去
    free(*L);
// 把调用者的指针置 NULL，避免它继续指向已释放的内存
    *L = NULL;
}


// 主函数不需要参数，返回 0 表示正常结束
int main(void)
{
// L 是头结点指针，先置 NULL，等 InitList 去创建头结点
    LinkList L = NULL;
// p 用来接 LocateElem 返回的结点地址
    LNode *p = NULL;
// e 用来接按位查找 / 删除带回来的数据
    ElemType e = 0;

// ========== 第 1 步：初始化 ==========
    printf("========== 1. 初始化 ==========\n");
// 检查返回值，初始化失败就没必要继续了
    if (InitList(&L) != OK)
    {
// 失败提示
        printf("初始化失败！\n");
// 直接返回错误码
        return ERROR;
    }
// 打印验证：此时应该是空表
    printf("初始化完成，当前链表：");
    printList(L);

// ========== 第 2 步：尾部追加 ==========
    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
// 依次追加三个数
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
// 期望输出：10 -> 20 -> 30 -> NULL
    printf("追加后：");
    printList(L);

// ========== 第 3 步：头插法 ==========
    printf("\n========== 3. 头插法插入 ==========\n");
// 头插 5：不遍历，直接变成第 1 个结点
    HeadInsert(L, 5);
// 期望输出：5 -> 10 -> 20 -> 30 -> NULL
    printf("头插后：");
    printList(L);

// 再头插 3，亲眼看一次"头插会颠倒顺序"
    HeadInsert(L, 3);
// 期望输出：3 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("再头插 3 后：");
    printList(L);

// ========== 第 4 步：按位插入 ==========
    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
// 插到第 2 个位置，即 3 和 5 之间
    ListInsert(L, 2, 15);
// 期望输出：3 -> 15 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("插入后：");
    printList(L);

// 越界测试：在第 99 位插入必须失败
    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 5 步：按位查找 ==========
    printf("\n========== 5. 按位查找 ==========\n");
// 查第 3 个元素，用 e 带回结果
    if (GetElem_L(L, 3, &e) == OK)
    {
// 期望输出：5
        printf("第 3 个元素的值是 %d\n", e);
    }
// 越界查找测试
    if (GetElem_L(L, 100, &e) == ERROR)
    {
// 期望走到这里
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

// ========== 第 6 步：按值查找 ==========
    printf("\n========== 6. 按值查找 ==========\n");
// 找值为 20 的结点
    p = LocateElem(L, 20);
// 找到就打印它的后继信息
    if (p != NULL)
    {
// p->next 非空则说明 20 不是尾结点
        printf("找到值为 20 的结点，它的后继是 %s\n", p->next != NULL ? "一个有效结点" : "NULL");
    }
// 找不存在的值应当返回 NULL
    if (LocateElem(L, 99) == NULL)
    {
// 期望走到这里
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

// ========== 第 7 步：按位删除 ==========
    printf("\n========== 7. 删除第 1 个结点 ==========\n");
// 删除第 1 个结点，被删的值通过 e 带出来
    if (ListDelete(L, 1, &e) == OK)
    {
// 期望输出：被删除的是 3
        printf("已删除第 1 个结点，它的值是 %d\n", e);
    }
// 期望输出：15 -> 5 -> 10 -> 20 -> 30 -> NULL
    printf("删除后：");
    printList(L);

// 越界删除测试
    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 8 步：释放整表 ==========
    printf("\n========== 8. 释放内存 ==========\n");
// 释放所有结点，并把 L 置为 NULL
    freeList(&L);
// 期望输出：NULL，证明 L 已被正确置空
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

// 正常结束
    return 0;
}

