#include <stdio.h>
#include <stdlib.h>

#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

typedef int Status;
typedef int ElemType;

typedef struct LNode {
    ElemType data;
    struct LNode *next;
} LNode, *LinkList;


LNode *creatNode(ElemType e)
{
    LNode *p = (LNode *)malloc(sizeof(LNode));

    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
        exit(OVERFLOW);
    }

    p->data = e;
    p->next = NULL;

    return p;
}


Status InitList(LinkList *L)
{
    *L = (LinkList)malloc(sizeof(LNode));
    if (*L == NULL) return ERROR;
    (*L)->next = NULL;
    return OK;
}


Status applist(LinkList L, ElemType e)
{
    LNode *p = L;
    LNode *s = NULL;

    if (L == NULL) return ERROR;

    while (p->next != NULL)
    {
        p = p->next;
    }

    s = creatNode(e);

    p->next = s;

    return OK;
}


Status HeadInsert(LinkList L, ElemType e)
{
    LNode *s = NULL;

    if (L == NULL) return ERROR;

    s = creatNode(e);

    s->next = L->next;
    L->next = s;

    return OK;
}


Status GetElem_L(LinkList L, int i, ElemType *e)
{
    LNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    return OK;
}


LNode *LocateElem(LinkList L, ElemType e)
{
    LNode *p = L->next;

    while (p != NULL && p->data != e)
    {
        p = p->next;
    }

    return p;
}


Status ListInsert(LinkList L, int i, ElemType e)
{
    LNode *p = L;
    LNode *s = NULL;
    int j = 0;

    while (p != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i - 1) return ERROR;

    s = creatNode(e);

    s->next = p->next;
    p->next = s;

    return OK;
}


Status ListDelete(LinkList L, int i, ElemType *e)
{
    LNode *p = L;
    LNode *q = NULL;
    int j = 0;

    while (p->next != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p->next == NULL || j > i - 1) return ERROR;

    q = p->next;
    *e = q->data;
    p->next = q->next;
    free(q);

    return OK;
}


void printList(LinkList L)
{
    LNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p != NULL)
    {
        printf("%d -> ", p->data);
        p = p->next;
    }

    printf("NULL\n");
}


void freeList(LinkList *L)
{
    LNode *p = (*L)->next;
    LNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}


int main(void)
{
    LinkList L = NULL;
    LNode *p = NULL;
    ElemType e = 0;

    printf("========== 1. 初始化 ==========\n");
    if (InitList(&L) != OK)
    {
        printf("初始化失败！\n");
        return ERROR;
    }
    printf("初始化完成，当前链表：");
    printList(L);

    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
    printf("追加后：");
    printList(L);

    printf("\n========== 3. 头插法插入 ==========\n");
    HeadInsert(L, 5);
    printf("头插后：");
    printList(L);

    HeadInsert(L, 3);
    printf("再头插 3 后：");
    printList(L);

    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
    ListInsert(L, 2, 15);
    printf("插入后：");
    printList(L);

    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

    printf("\n========== 5. 按位查找 ==========\n");
    if (GetElem_L(L, 3, &e) == OK)
    {
        printf("第 3 个元素的值是 %d\n", e);
    }
    if (GetElem_L(L, 100, &e) == ERROR)
    {
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

    printf("\n========== 6. 按值查找 ==========\n");
    p = LocateElem(L, 20);
    if (p != NULL)
    {
        printf("找到值为 20 的结点，它的后继是 %s\n", p->next != NULL ? "一个有效结点" : "NULL");
    }
    if (LocateElem(L, 99) == NULL)
    {
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

    printf("\n========== 7. 删除第 1 个结点 ==========\n");
    if (ListDelete(L, 1, &e) == OK)
    {
        printf("已删除第 1 个结点，它的值是 %d\n", e);
    }
    printf("删除后：");
    printList(L);

    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

    printf("\n========== 8. 释放内存 ==========\n");
    freeList(&L);
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

    return 0;
}

modes.detail:
// ============ 相比单链表，结构体里多了什么 ============
//
//   单链表：  typedef struct LNode  { ElemType data; struct LNode  *next;  } LNode,  *LinkList;
//   双向链表：typedef struct DuLNode { ElemType data; struct DuLNode *prior;
//                                                     struct DuLNode *next;  } DuLNode, *DuLinkList;
//
// 就多了一个 prior。命名上习惯用 Du 前缀（double）把两者区分开 ——
// 一份代码里同时出现单链表和双向链表时，这个前缀能救命。
//
// ============ 内存里长什么样 ============
//
//   [头] ⇄ [10] ⇄ [20] ⇄ [30]
//    L
//
// 屏幕上每个 ⇄ 在内存里其实是**两根方向相反**的指针。
// 把每个结点的两个指针摊开列出来：
//
//   [头]：prior = NULL、next = [10]
//   [10]：prior = [头]、next = [20]
//   [20]：prior = [10]、next = [30]
//   [30]：prior = [20]、next = NULL
//
// 只有头结点的 prior 是 NULL（它前面没有结点了），
// 只有尾结点的 next 是 NULL（它后面没有结点了）。
// 这两条性质后面写插入、删除时会反复用到 —— 尤其是"要不要判空"。

// 标准输入输出，printf 需要
#include <stdio.h>
// 内存管理，malloc / free 需要
#include <stdlib.h>

// 用宏定义状态码，让函数返回值有意义（比裸 1 / 0 好读）
// 约定：函数返回 Status，OK 表示成功，ERROR 表示失败
#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
// 内存分配失败的专用错误码，取一个和 OK/ERROR 都不冲突的负数
#define OVERFLOW -2

// Status 是函数返回类型；ElemType 是数据域类型
typedef int Status;
typedef int ElemType;

// 双向结点：数据域 + 前驱指针 + 后继指针
// 两个指针的分工：
//   prior  指向前一个结点，头结点和"第一个数据结点"的 prior 关系要注意
//   next   指向后一个结点，最后一个结点的 next 是 NULL
//
// 有一条贯穿全书的等式，插入删除时全靠它自检：
//
//     p->next->prior == p        以及        p->prior->next == p
//
// 也就是"我指向谁，谁就得指回我"。写双向链表的代码时，每改一次指针
// 都拿这句话对一遍，基本不会错。
typedef struct DuLNode {
// 数据域，存具体元素
    ElemType data;
// 前驱指针：指向上一个结点（这是单链表没有的）
    struct DuLNode *prior;
// 后继指针：指向下一个结点，尾结点为 NULL
    struct DuLNode *next;
// 一次 typedef 出两个名字：DuLNode（结点）和 DuLinkList（指向结点的指针）
} DuLNode, *DuLinkList;

