modes.detail:
// ============ 比单链表多置一个指针 ============
// 单链表的新结点只需要 p->next = NULL；
// 双向链表必须**两个方向都置 NULL**，否则 prior 就是野指针，
// 后面一旦顺着 prior 往回走（比如反向遍历）就会访问到非法内存。
//
// 这个函数只负责"造出一个孤立的结点"，它还没有被挂到任何链表上，
// 所以两个指针都应该是干净的 NULL。

// 返回新结点的地址，所以返回类型是 DuLNode *
DuLNode *creatNode(ElemType e)
{
// 申请一个结点大小的内存，强制转换成 DuLNode *
// 双向结点比单链表结点大一个指针：32 位下 12 字节，64 位下 24 字节
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

// 申请失败必须拦住，否则后面 p->data 就是非法访问
    if (p == NULL)
    {
// 打印中文提示，让使用者知道是内存不够，而不是程序莫名其妙退出
        printf("内存分配失败：无法创建新结点。\n");
// 申请不到内存属于致命错误，直接结束程序
        exit(OVERFLOW);
    }

// 填数据域
    p->data = e;
// 前驱置 NULL（单链表没有这一步）
    p->prior = NULL;
// 后继置 NULL
// 两个方向都干净了，结点才算"造好但还没上链"
    p->next = NULL;

// 把新结点的地址返回给调用者
    return p;
}

