modes.detail:
// ============ 双向链表比单链表多改一根指针 ============
// 单链表尾插只有一步：p->next = s;
// 双向链表要做两步，而且两步都要做：
//
//     s->prior = p;      ← 新结点回指旧的尾结点
//     p->next  = s;      ← 旧尾结点指向新结点
//
// 少了第一句，整条链表从后往前就断了：正向遍历看不出来，一旦反向遍历
// （或者删除尾结点时用 p->prior）就会踩到野指针。
//
// ============ 指针推进过程 ============
// 目标：在尾部追加 30
//
//  初始：  L ─▶ [头] ⇄ [10] ⇄ [20]
//          p
//
//  循环：  L ─▶ [头] ⇄ [10] ⇄ [20]
//                              p        （p->next == NULL，p 就是尾结点）
//
//  挂链：  L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
// 注意 [20] 和 [30] 之间是**双向**的箭头，两根指针缺一不可。

// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
Status applist(DuLinkList L, ElemType e)
{
// p 是"游标"，从头结点开始；它最终会停在尾结点上
    DuLNode *p = L;
// s 用来接住 creatNode 造出来的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 一路向后走，直到 p 后面没有结点了
// 循环条件是 p->next != NULL，看的永远是"下一个"，所以停下时 p 正是尾结点
    while (p->next != NULL)
    {
// 指针后移一格
        p = p->next;
    }

// 造新结点（此时它的 prior 和 next 都是 NULL）
    s = creatNode(e);

// 第一步：新结点的 prior 回指旧的尾结点
// 这一句是双向链表特有的，单链表尾插没有
    s->prior = p;
// 第二步：旧尾结点的 next 指向新结点
// 两句都做完，[p] ⇄ [s] 这条双向关系才成立
    p->next = s;

// 返回 OK 表示追加成功
    return OK;
}

