modes.detail:
// ============ 头插法的特点 ============
//
//   applist（尾插）  ：从头一路走到尾             —— 时间复杂度 O(n)
//   HeadInsert（头插）：直接插在头结点后面        —— 时间复杂度 O(1)
//
// 代价是头插会**颠倒顺序**：依次头插 10、20、30，得到的是 30 ⇄ 20 ⇄ 10。
// 这不是缺陷 —— "头插法建表"正是靠它做逆序的。
//
// 再记住一个等价关系：HeadInsert(L, e) 和 ListInsert(L, 1, e) 干的是同一件事。
//
// ============ 双向链表的头插为什么必须判空表 ============
// 单链表头插只有两句，不用管表是不是空的：
//
//     s->next = L->next;
//     L->next = s;
//
// 双向链表要处理的指针多一根，而且有一句**在空表时是非法操作**：
//
//     s->next = L->next;
//     if (s->next != NULL)  s->next->prior = s;    ← 必须判空！
//     s->prior = L;
//     L->next = s;
//
// 空表时 L->next 是 NULL，如果不判空就去写 s->next->prior，
// 等于对空指针取成员 —— 程序当场崩溃。这是双向链表头插最经典的坑。
//
// ============ 插入前后 ============
// 把 5 头插进 10 ⇄ 20
//
//  插入前：  L ─▶ [头] ⇄ [10] ⇄ [20]
//
//  四步做完：
//           L ─▶ [头] ⇄ [5] ⇄ [10] ⇄ [20]
//
// 其中 [5] 与 [头]、[5] 与 [10] 之间都要是双向的。

// 参数 L 是头结点指针，不需要改 L 本身
// 位置固定在第 1 位，所以不需要 i 这个参数
Status HeadInsert(DuLinkList L, ElemType e)
{
// s 是等待挂链的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过
    if (L == NULL) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点的 next 接住原来头结点后面的那一串
    s->next = L->next;
// 第二步：如果后面确实有结点，让它的 prior 改指新结点
// 这一步必须判空：空表时 L->next 是 NULL，s->next->prior 就是空指针取成员
    if (s->next != NULL)
    {
        s->next->prior = s;
    }
// 第三步：新结点的 prior 指向头结点
// 头结点一定存在，所以这一句不需要判空
    s->prior = L;
// 第四步：头结点指向新结点，s 正式成为第 1 个结点
    L->next = s;

// 插入成功
    return OK;
}

