// ============ 这段代码和单链表完全一样 ============
// 按位查找只需要沿 next 往后走，"双向"在这里帮不上忙
// —— 除非你想从尾部倒着数，但那需要先知道表长，通常不划算。
// （进阶：有的实现会额外记录 length，那样 i 大于一半时可以从尾结点
//   顺着 prior 往前找，代价是每次插入删除都要维护 length。本教材从简。）
//
// ============ 找第 3 个结点（i = 3）============
//
//   L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//          j=1     j=2     j=3
//           p       p       p
//
// 两个必须同时检查的失败情况：
//   p == NULL  → i 比表长还大，数着数着掉出去了
//   j > i      → i 小于 1（比如 i = 0），循环一次都没进

// 结果通过 e 带回去，所以要传 ElemType *（地址），不是 ElemType
Status GetElem_L(DuLinkList L, int i, ElemType *e)
{
// 从第 1 个"带数据的结点"开始，所以是 L->next 而不是 L
    DuLNode *p = L->next;
// 计数器 j 与 p 同步，表示"p 现在指的是第几个结点"
    int j = 1;

// 边走边数，直到数到 i 或者走到表尾
// p != NULL 写在前面，短路求值保证不会对空指针取 ->next
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步加一
        j++;
    }

// 越界检查：p 为空说明 i 超过表长；j > i 说明 i 小于 1
    if (p == NULL || j > i) return ERROR;

// 把找到的数据写到调用者提供的地址里
    *e = p->data;

// 查找成功
    return OK;
}

