modes.detail:
// ============ 按值查找返回的是"结点"不是"值" ============
// 拿回结点地址后，调用者还能继续访问它的 prior / next，
// 也能在它前后做插入删除 —— 这比只拿回一个数据值有用得多。
//
// 找不到时返回 NULL，这是 C 语言表示"没有这个结点"的标准做法。
//
// 双向链表在这里同样没有优势（按值查找本身就是逐个比对），
// 除非链表是按别的规则组织过的。

// 返回 DuLNode *，找不到就是 NULL
DuLNode *LocateElem(DuLinkList L, ElemType e)
{
// 同样从第一个带数据的结点开始
    DuLNode *p = L->next;

// 两个条件：还没走到尾，且当前值不等于目标
// 一旦 p->data == e，循环立刻停下，p 就停在第一个匹配的结点上
    while (p != NULL && p->data != e)
    {
// 不匹配就继续往后
        p = p->next;
    }

// 找到返回地址，没找到时 p 已经是 NULL，直接返回即可
    return p;
}

