modes.detail:
// ============ 改和查是一对 ============
// 把 ModifyElem 和 GetElem_L 摆在一起看，会发现它们**只差最后一句**：
//
//     GetElem_L ：  *e = p->data;     把结点里的值读出来
//     ModifyElem ：  p->data = e;     把新值写进结点
//
// 前面"走 i-1 步定位"的循环、以及越界检查，两者一模一样。
// 这也说明一件事：**定位是链表操作里最通用的部分**，
// 插入、删除、查找、修改都要先定位，区别只在定位到第几个结点、
// 以及定位之后动几根指针。
//
// ============ 修改只动数据域，不动指针 ============
// 这一点很重要：改一个结点的值不会改变链表的形状，
// 所以不需要碰 prior / next，也就不会有双向链表那些"漏改一根指针"的风险。
//
// 代价是修改**不能改变链表的顺序**。如果你要的是"把某个值挪到前面"，
// 那得先删除再插入，属于删+插的组合操作。

// 要改的目标值通过 e 传进来（按值传递就够了，不需要指针）
Status ModifyElem(DuLinkList L, int i, ElemType e)
{
// 从第 1 个"带数据的结点"开始
    DuLNode *p = L->next;
// 计数器 j 与 p 同步
    int j = 1;

// 定位到第 i 个结点（与 GetElem_L 的循环完全相同）
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：第 i 个结点不存在就报错
    if (p == NULL || j > i) return ERROR;

// 把新值写进数据域 —— 只改数据，不碰任何指针
    p->data = e;

// 修改成功
    return OK;
}

