} DuLNode, *DuLinkList;

/* ======== [已给出] 模块 02 creatNode ======== */

DuLNode *creatNode(ElemType e)
{
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
        exit(OVERFLOW);
    }

    p->data = e;
    p->prior = NULL;
    p->next = NULL;

    return p;
}

/* ======== [已给出] 模块 03 InitList ======== */

Status InitList(DuLinkList *L)
{
    *L = (DuLinkList)malloc(sizeof(DuLNode));
    if (*L == NULL) return ERROR;
    (*L)->prior = NULL;
    (*L)->next = NULL;
    return OK;
}

/* ======== [已给出] 模块 04 applist ======== */

Status applist(DuLinkList L, ElemType e)
{
    DuLNode *p = L;
    DuLNode *s = NULL;

    if (L == NULL) return ERROR;

    while (p->next != NULL)
    {
        p = p->next;
    }

    s = creatNode(e);

    s->prior = p;
    p->next = s;

    return OK;
}

/* ======== [已给出] 模块 11 printList ======== */

void printList(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p != NULL)
    {
        printf("%d ⇄ ", p->data);
        p = p->next;
    }

    printf("NULL\n");
}

/* ======== [已给出] 模块 12 printListReverse ======== */

void printListReverse(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p->next != NULL)
    {
        p = p->next;
    }

    while (p != L)
    {
        printf("%d ⇄ ", p->data);
        p = p->prior;
    }

    printf("NULL\n");
}

/* ======== [已给出] 模块 13 freeList ======== */

void freeList(DuLinkList *L)
{
    DuLNode *p = (*L)->next;
    DuLNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}

