// ============ 正向遍历：和单链表一模一样 ============
//
//   p = L->next;              ← 跳过不存数据的头结点
//   while (p != NULL) {       ← 走到 NULL 说明到尾了
//       ... 处理 p->data ...
//       p = p->next;          ← 千万别忘了这一句，否则死循环
//   }
//
// 输出用 `⇄` 而不是 `->`，是为了提醒这条链是**双向**的：
// 屏幕上看到的每个 `⇄`，在内存里都对应两根指针。
//
// 真正体现双向价值的是下一个模块 —— 反向打印。

// 只读操作，参数直接传 DuLinkList（一级指针）
void printList(DuLinkList L)
{
// 从第一个真实结点开始
    DuLNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，`⇄` 表示这里是双向连接
        printf("%d ⇄ ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}

