modes.detail:
// ============ 这就是双向链表多一个指针换来的能力 ============
// 单链表想倒着打印，只有两条路：
//   1. 递归（函数调用栈替你记住来路，但表长了会爆栈）；
//   2. 先把数据全拷进数组，再倒着输出（额外 O(n) 空间）。
// 双向链表不用这么麻烦 —— prior 就在结点里，直接往回走。
//
// ============ 为什么循环条件是 p != L 而不是 p != NULL ============
// 这是本模块最容易写错的地方。
//
//   反向走的时候，如果写 while (p != NULL)：
//     p 会一路走过头结点，而头结点的 data 是**没意义的垃圾值**，
//     屏幕上会莫名其妙多打一个数；再往后 p 变成 NULL 才停。
//
//   正确写法是 while (p != L)：
//     走到头结点就停 —— 头结点是哨兵，不该被当成数据打印。
//
// 顺带一提：正因为头结点的 prior 是 NULL，如果哪一步把"停"的条件写错，
// 就会顺着 NULL 继续取 prior，直接崩掉。
//
// ============ 走法示意 ============
//
//  第一步：顺着 next 找到尾结点
//    L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//                                  p
//
//  第二步：顺着 prior 一路往回，边走边打印，直到撞上头结点
//    L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//            p ◀──── 返回路径
//
//  屏幕上得到：  30 ⇄ 20 ⇄ 10 ⇄ NULL

// 只读操作，不需要修改链表
void printListReverse(DuLinkList L)
{
// 从头结点后面开始
    DuLNode *p = L->next;

// 空表同样单独处理
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回
        return;
    }

// 第一步：顺着 next 走到尾结点
// 条件写 p->next != NULL，所以停下时 p 正好是最后一个结点
    while (p->next != NULL)
    {
// 指针后移
        p = p->next;
    }

// 第二步：顺着 prior 往回走，撞到头结点就停
// 这里必须写 p != L，不能写 p != NULL —— 头结点不能被当成数据打印
    while (p != L)
    {
// 打印当前数据
        printf("%d ⇄ ", p->data);
// 顺着 prior 往回走一格（单链表没有这一步可走）
        p = p->prior;
    }

// 收尾
    printf("NULL\n");
}

