modes.detail:
// ============ 释放只需要 next 方向 ============
// 虽然结点里有 prior，但释放时**根本用不到它** ——
// 因为必须先把整条链走完才能全部释放，而"走完"只需要 next。
//
// ============ 为什么必须先保存 next ============
//
//  错误写法：                正确写法：
//    free(p);                  q = p;
//    p = p->next;   ← 危险!    p = p->next;
//                             free(q);
//
// free(p) 之后那块内存已经还给系统，p->next 读到的是垃圾值，
// 用这个垃圾值当地址去访问就是"释放后使用"（use after free）。
//
// 更危险的是：如果在 free(p) 之前先去动 p->prior->next 之类的指针
// （双向链表很容易顺手这么写），会把已经损坏的链再改一次，
// 崩溃点离真正的错误点非常远，极难排查。

// 参数是 DuLinkList *，因为最后要把调用者的 L 改成 NULL
void freeList(DuLinkList *L)
{
// 从第一个真实结点开始清理
    DuLNode *p = (*L)->next;
// q 用来暂存"即将被释放"的那个结点
    DuLNode *q = NULL;

// 逐个结点释放
    while (p != NULL)
    {
// 先记住当前结点
        q = p;
// 再让 p 走到下一个（此时 p 已经安全了）
        p = p->next;
// 最后才释放 q
// 这三步顺序固定：存 → 走 → 放，缺一不可
        free(q);
    }

// 数据结点都清完了，头结点也要还回去
    free(*L);
// 把调用者的指针置 NULL，避免它继续指向已释放的内存
    *L = NULL;
}

