/* ======== [已给出] 模块 01 头文件与 typedef ======== */

#include <stdio.h>
#include <stdlib.h>

#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

typedef int Status;
typedef int ElemType;

typedef struct DuLNode {
    ElemType data;
    struct DuLNode *prior;
    struct DuLNode *next;
} DuLNode, *DuLinkList;

/* ======== [已给出] 模块 02 creatNode ======== */

DuLNode *creatNode(ElemType e)
{
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
        exit(OVERFLOW);
    }

    p->data = e;
    p->prior = NULL;
    p->next = NULL;

    return p;
}

/* ======== [已给出] 模块 03 InitList ======== */

Status InitList(DuLinkList *L)
{
    *L = (DuLinkList)malloc(sizeof(DuLNode));
    if (*L == NULL) return ERROR;
    (*L)->prior = NULL;
    (*L)->next = NULL;
    return OK;
}

/* ======== [已给出] 模块 04 applist ======== */

Status applist(DuLinkList L, ElemType e)
{
    DuLNode *p = L;
    DuLNode *s = NULL;

    if (L == NULL) return ERROR;

    while (p->next != NULL)
    {
        p = p->next;
    }

    s = creatNode(e);

    s->prior = p;
    p->next = s;

    return OK;
}

/* ======== [已给出] 模块 05 HeadInsert ======== */

Status HeadInsert(DuLinkList L, ElemType e)
{
    DuLNode *s = NULL;

    if (L == NULL) return ERROR;

    s = creatNode(e);

    s->next = L->next;
    if (s->next != NULL)
    {
        s->next->prior = s;
    }
    s->prior = L;
    L->next = s;

    return OK;
}

/* ======== [已给出] 模块 06 GetElem_L ======== */

Status GetElem_L(DuLinkList L, int i, ElemType *e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    return OK;
}

/* ======== [已给出] 模块 07 LocateElem ======== */

DuLNode *LocateElem(DuLinkList L, ElemType e)
{
    DuLNode *p = L->next;

    while (p != NULL && p->data != e)
    {
        p = p->next;
    }

    return p;
}

/* ======== [已给出] 模块 08 ModifyElem ======== */

Status ModifyElem(DuLinkList L, int i, ElemType e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    p->data = e;

    return OK;
}

/* ======== [已给出] 模块 09 ListInsert ======== */

Status ListInsert(DuLinkList L, int i, ElemType e)
{
    DuLNode *p = L;
    DuLNode *s = NULL;
    int j = 0;

    while (p != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i - 1) return ERROR;

    s = creatNode(e);

    s->next = p->next;
    if (p->next != NULL)
    {
        p->next->prior = s;
    }
    s->prior = p;
    p->next = s;

    return OK;
}

/* ======== [已给出] 模块 10 ListDelete ======== */

Status ListDelete(DuLinkList L, int i, ElemType *e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    p->prior->next = p->next;
    if (p->next != NULL)
    {
        p->next->prior = p->prior;
    }
    free(p);

    return OK;
}

/* ======== [已给出] 模块 11 printList ======== */

void printList(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p != NULL)
    {
        printf("%d ⇄ ", p->data);
        p = p->next;
    }

    printf("NULL\n");
}

/* ======== [已给出] 模块 12 printListReverse ======== */

void printListReverse(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p->next != NULL)
    {
        p = p->next;
    }

    while (p != L)
    {
        printf("%d ⇄ ", p->data);
        p = p->prior;
    }

    printf("NULL\n");
}

/* ======== [已给出] 模块 13 freeList ======== */

void freeList(DuLinkList *L)
{
    DuLNode *p = (*L)->next;
    DuLNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}

/* ====================================================================
 *  轮到你了：模块 14  main
 *  作用：把增、删、查、改四类操作各跑一遍，正反向遍历对照验证 prior 没写错。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */

modes.detail:
// ============ 相比单链表，结构体里多了什么 ============
//
//   单链表：  typedef struct LNode  { ElemType data; struct LNode  *next;  } LNode,  *LinkList;
//   双向链表：typedef struct DuLNode { ElemType data; struct DuLNode *prior;
//                                                     struct DuLNode *next;  } DuLNode, *DuLinkList;
//
// 就多了一个 prior。命名上习惯用 Du 前缀（double）把两者区分开 ——
// 一份代码里同时出现单链表和双向链表时，这个前缀能救命。
//
// ============ 内存里长什么样 ============
//
//   [头] ⇄ [10] ⇄ [20] ⇄ [30]
//    L
//
// 屏幕上每个 ⇄ 在内存里其实是**两根方向相反**的指针。
// 把每个结点的两个指针摊开列出来：
//
//   [头]：prior = NULL、next = [10]
//   [10]：prior = [头]、next = [20]
//   [20]：prior = [10]、next = [30]
//   [30]：prior = [20]、next = NULL
//
// 只有头结点的 prior 是 NULL（它前面没有结点了），
// 只有尾结点的 next 是 NULL（它后面没有结点了）。
// 这两条性质后面写插入、删除时会反复用到 —— 尤其是"要不要判空"。

// 标准输入输出，printf 需要
#include <stdio.h>
// 内存管理，malloc / free 需要
#include <stdlib.h>

// 用宏定义状态码，让函数返回值有意义（比裸 1 / 0 好读）
// 约定：函数返回 Status，OK 表示成功，ERROR 表示失败
#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
// 内存分配失败的专用错误码，取一个和 OK/ERROR 都不冲突的负数
#define OVERFLOW -2

// Status 是函数返回类型；ElemType 是数据域类型
typedef int Status;
typedef int ElemType;

// 双向结点：数据域 + 前驱指针 + 后继指针
// 两个指针的分工：
//   prior  指向前一个结点，头结点和"第一个数据结点"的 prior 关系要注意
//   next   指向后一个结点，最后一个结点的 next 是 NULL
//
// 有一条贯穿全书的等式，插入删除时全靠它自检：
//
//     p->next->prior == p        以及        p->prior->next == p
//
// 也就是"我指向谁，谁就得指回我"。写双向链表的代码时，每改一次指针
// 都拿这句话对一遍，基本不会错。
typedef struct DuLNode {
// 数据域，存具体元素
    ElemType data;
// 前驱指针：指向上一个结点（这是单链表没有的）
    struct DuLNode *prior;
// 后继指针：指向下一个结点，尾结点为 NULL
    struct DuLNode *next;
// 一次 typedef 出两个名字：DuLNode（结点）和 DuLinkList（指向结点的指针）
} DuLNode, *DuLinkList;

// ============ 比单链表多置一个指针 ============
// 单链表的新结点只需要 p->next = NULL；
// 双向链表必须**两个方向都置 NULL**，否则 prior 就是野指针，
// 后面一旦顺着 prior 往回走（比如反向遍历）就会访问到非法内存。
//
// 这个函数只负责"造出一个孤立的结点"，它还没有被挂到任何链表上，
// 所以两个指针都应该是干净的 NULL。

// 返回新结点的地址，所以返回类型是 DuLNode *
DuLNode *creatNode(ElemType e)
{
// 申请一个结点大小的内存，强制转换成 DuLNode *
// 双向结点比单链表结点大一个指针：32 位下 12 字节，64 位下 24 字节
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

// 申请失败必须拦住，否则后面 p->data 就是非法访问
    if (p == NULL)
    {
// 打印中文提示，让使用者知道是内存不够，而不是程序莫名其妙退出
        printf("内存分配失败：无法创建新结点。\n");
// 申请不到内存属于致命错误，直接结束程序
        exit(OVERFLOW);
    }

// 填数据域
    p->data = e;
// 前驱置 NULL（单链表没有这一步）
    p->prior = NULL;
// 后继置 NULL
// 两个方向都干净了，结点才算"造好但还没上链"
    p->next = NULL;

// 把新结点的地址返回给调用者
    return p;
}

// ============ 头结点在双向链表里的特殊性 ============
// 头结点是"哨兵"：不存有效数据，只为让插入/删除不用特判第一个位置。
// 在双向链表里它还有两条铁律：
//
//   1. 头结点的 prior 永远是 NULL —— 它前面没有结点了；
//   2. 头结点的 next 指向第一个数据结点（空表时是 NULL）。
//
// 空表的样子：
//
//        ┌────┬──────┬──────┐
//        │NULL│  --  │ NULL │
//        └────┴──────┴──────┘
//          L
//
// 因为头结点的 prior 是 NULL，"第一个数据结点的 prior 指向头结点"这条关系
// 才和中间结点完全一致 —— 这就是后面删除时 p->prior 不用判空的原因。

// 参数是 DuLinkList *（二级指针），因为要修改调用者手里的 L 本身
Status InitList(DuLinkList *L)
{
// 只申请头结点，不存数据
    *L = (DuLinkList)malloc(sizeof(DuLNode));
// 头结点也可能申请失败
    if (*L == NULL) return ERROR;
// 头结点的 prior 恒为 NULL，写出来是为了明确这条不变式
    (*L)->prior = NULL;
// 空表的标志：头结点的 next 为 NULL
    (*L)->next = NULL;
// 返回 OK 表示初始化成功
    return OK;
}

// ============ 双向链表比单链表多改一根指针 ============
// 单链表尾插只有一步：p->next = s;
// 双向链表要做两步，而且两步都要做：
//
//     s->prior = p;      ← 新结点回指旧的尾结点
//     p->next  = s;      ← 旧尾结点指向新结点
//
// 少了第一句，整条链表从后往前就断了：正向遍历看不出来，一旦反向遍历
// （或者删除尾结点时用 p->prior）就会踩到野指针。
//
// ============ 指针推进过程 ============
// 目标：在尾部追加 30
//
//  初始：  L ─▶ [头] ⇄ [10] ⇄ [20]
//          p
//
//  循环：  L ─▶ [头] ⇄ [10] ⇄ [20]
//                              p        （p->next == NULL，p 就是尾结点）
//
//  挂链：  L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
// 注意 [20] 和 [30] 之间是**双向**的箭头，两根指针缺一不可。

// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
Status applist(DuLinkList L, ElemType e)
{
// p 是"游标"，从头结点开始；它最终会停在尾结点上
    DuLNode *p = L;
// s 用来接住 creatNode 造出来的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 一路向后走，直到 p 后面没有结点了
// 循环条件是 p->next != NULL，看的永远是"下一个"，所以停下时 p 正是尾结点
    while (p->next != NULL)
    {
// 指针后移一格
        p = p->next;
    }

// 造新结点（此时它的 prior 和 next 都是 NULL）
    s = creatNode(e);

// 第一步：新结点的 prior 回指旧的尾结点
// 这一句是双向链表特有的，单链表尾插没有
    s->prior = p;
// 第二步：旧尾结点的 next 指向新结点
// 两句都做完，[p] ⇄ [s] 这条双向关系才成立
    p->next = s;

// 返回 OK 表示追加成功
    return OK;
}

// ============ 头插法的特点 ============
//
//   applist（尾插）  ：从头一路走到尾             —— 时间复杂度 O(n)
//   HeadInsert（头插）：直接插在头结点后面        —— 时间复杂度 O(1)
//
// 代价是头插会**颠倒顺序**：依次头插 10、20、30，得到的是 30 ⇄ 20 ⇄ 10。
// 这不是缺陷 —— "头插法建表"正是靠它做逆序的。
//
// 再记住一个等价关系：HeadInsert(L, e) 和 ListInsert(L, 1, e) 干的是同一件事。
//
// ============ 双向链表的头插为什么必须判空表 ============
// 单链表头插只有两句，不用管表是不是空的：
//
//     s->next = L->next;
//     L->next = s;
//
// 双向链表要处理的指针多一根，而且有一句**在空表时是非法操作**：
//
//     s->next = L->next;
//     if (s->next != NULL)  s->next->prior = s;    ← 必须判空！
//     s->prior = L;
//     L->next = s;
//
// 空表时 L->next 是 NULL，如果不判空就去写 s->next->prior，
// 等于对空指针取成员 —— 程序当场崩溃。这是双向链表头插最经典的坑。
//
// ============ 插入前后 ============
// 把 5 头插进 10 ⇄ 20
//
//  插入前：  L ─▶ [头] ⇄ [10] ⇄ [20]
//
//  四步做完：
//           L ─▶ [头] ⇄ [5] ⇄ [10] ⇄ [20]
//
// 其中 [5] 与 [头]、[5] 与 [10] 之间都要是双向的。

// 参数 L 是头结点指针，不需要改 L 本身
// 位置固定在第 1 位，所以不需要 i 这个参数
Status HeadInsert(DuLinkList L, ElemType e)
{
// s 是等待挂链的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过
    if (L == NULL) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点的 next 接住原来头结点后面的那一串
    s->next = L->next;
// 第二步：如果后面确实有结点，让它的 prior 改指新结点
// 这一步必须判空：空表时 L->next 是 NULL，s->next->prior 就是空指针取成员
    if (s->next != NULL)
    {
        s->next->prior = s;
    }
// 第三步：新结点的 prior 指向头结点
// 头结点一定存在，所以这一句不需要判空
    s->prior = L;
// 第四步：头结点指向新结点，s 正式成为第 1 个结点
    L->next = s;

// 插入成功
    return OK;
}

// ============ 这段代码和单链表完全一样 ============
// 按位查找只需要沿 next 往后走，"双向"在这里帮不上忙
// —— 除非你想从尾部倒着数，但那需要先知道表长，通常不划算。
// （进阶：有的实现会额外记录 length，那样 i 大于一半时可以从尾结点
//   顺着 prior 往前找，代价是每次插入删除都要维护 length。本教材从简。）
//
// ============ 找第 3 个结点（i = 3）============
//
//   L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//          j=1     j=2     j=3
//           p       p       p
//
// 两个必须同时检查的失败情况：
//   p == NULL  → i 比表长还大，数着数着掉出去了
//   j > i      → i 小于 1（比如 i = 0），循环一次都没进

// 结果通过 e 带回去，所以要传 ElemType *（地址），不是 ElemType
Status GetElem_L(DuLinkList L, int i, ElemType *e)
{
// 从第 1 个"带数据的结点"开始，所以是 L->next 而不是 L
    DuLNode *p = L->next;
// 计数器 j 与 p 同步，表示"p 现在指的是第几个结点"
    int j = 1;

// 边走边数，直到数到 i 或者走到表尾
// p != NULL 写在前面，短路求值保证不会对空指针取 ->next
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步加一
        j++;
    }

// 越界检查：p 为空说明 i 超过表长；j > i 说明 i 小于 1
    if (p == NULL || j > i) return ERROR;

// 把找到的数据写到调用者提供的地址里
    *e = p->data;

// 查找成功
    return OK;
}

// ============ 按值查找返回的是"结点"不是"值" ============
// 拿回结点地址后，调用者还能继续访问它的 prior / next，
// 也能在它前后做插入删除 —— 这比只拿回一个数据值有用得多。
//
// 找不到时返回 NULL，这是 C 语言表示"没有这个结点"的标准做法。
//
// 双向链表在这里同样没有优势（按值查找本身就是逐个比对），
// 除非链表是按别的规则组织过的。

// 返回 DuLNode *，找不到就是 NULL
DuLNode *LocateElem(DuLinkList L, ElemType e)
{
// 同样从第一个带数据的结点开始
    DuLNode *p = L->next;

// 两个条件：还没走到尾，且当前值不等于目标
// 一旦 p->data == e，循环立刻停下，p 就停在第一个匹配的结点上
    while (p != NULL && p->data != e)
    {
// 不匹配就继续往后
        p = p->next;
    }

// 找到返回地址，没找到时 p 已经是 NULL，直接返回即可
    return p;
}

// ============ 改和查是一对 ============
// 把 ModifyElem 和 GetElem_L 摆在一起看，会发现它们**只差最后一句**：
//
//     GetElem_L ：  *e = p->data;     把结点里的值读出来
//     ModifyElem ：  p->data = e;     把新值写进结点
//
// 前面"走 i-1 步定位"的循环、以及越界检查，两者一模一样。
// 这也说明一件事：**定位是链表操作里最通用的部分**，
// 插入、删除、查找、修改都要先定位，区别只在定位到第几个结点、
// 以及定位之后动几根指针。
//
// ============ 修改只动数据域，不动指针 ============
// 这一点很重要：改一个结点的值不会改变链表的形状，
// 所以不需要碰 prior / next，也就不会有双向链表那些"漏改一根指针"的风险。
//
// 代价是修改**不能改变链表的顺序**。如果你要的是"把某个值挪到前面"，
// 那得先删除再插入，属于删+插的组合操作。

// 要改的目标值通过 e 传进来（按值传递就够了，不需要指针）
Status ModifyElem(DuLinkList L, int i, ElemType e)
{
// 从第 1 个"带数据的结点"开始
    DuLNode *p = L->next;
// 计数器 j 与 p 同步
    int j = 1;

// 定位到第 i 个结点（与 GetElem_L 的循环完全相同）
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：第 i 个结点不存在就报错
    if (p == NULL || j > i) return ERROR;

// 把新值写进数据域 —— 只改数据，不碰任何指针
    p->data = e;

// 修改成功
    return OK;
}

// ============ 双向链表插入要动四根指针 ============
// 单链表插入动两根：
//
//     s->next = p->next;
//     p->next = s;
//
// 双向链表要动四根，因为新结点和前后两个邻居都要建立双向关系：
//
//     ① s->next = p->next;
//     ② if (p->next != NULL)  p->next->prior = s;
//     ③ s->prior = p;
//     ④ p->next = s;
//
// ①③ 是"新结点指出去"，②④ 是"邻居指回来"。四句缺一句，
// 链表就会变成"一个方向通、另一个方向断"——正向遍历一切正常，
// 反向遍历或后续删除时突然崩溃。这是最难查的一类 bug。
//
// ============ ②为什么要判空 ============
// 如果 i 正好等于表长 +1（插到表尾），那么 p->next 是 NULL，
// 此时 p 后面没有结点，也就没有人需要把 prior 指回来。
// 不判空就直接写 p->next->prior，等于对空指针取成员，程序当场崩溃。
//
// ============ 四步做完的过程 ============
// 目标：在第 2 个位置插入 15（即 [10] 之后）
//
//  插入前：  L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//                       p
//
//  ① s->next = p->next
//          [15] ──▶ [20]            （此时 p->next 还指着 [20]）
//
//  ② p->next->prior = s
//          [20] ◀── [15]            （[20] 的前驱从 [10] 改成 [15]）
//
//  ③ s->prior = p
//          [10] ◀── [15]            （[15] 的前驱指向 [10]）
//
//  ④ p->next = s
//          [10] ──▶ [15]            （[10] 的后继从 [20] 改成 [15]）
//
//  插入后：  L ─▶ [头] ⇄ [10] ⇄ [15] ⇄ [20] ⇄ [30]
//
// 还有一条铁律：**先判断能不能插，再造结点**。顺序颠倒会导致插入失败时
// 白白多出一个没挂上链表的"孤儿结点"。

// 参数 L 是头结点指针；i 是位置，e 是数据
// 位置 i 从 1 开始计数，表示"插完以后它是第 i 个结点"
Status ListInsert(DuLinkList L, int i, ElemType e)
{
// p 要从头结点开始：因为插到第 1 位时，前驱就是头结点
    DuLNode *p = L;
// s 是等待挂链的新结点
    DuLNode *s = NULL;
// j 表示 p 当前指向第几个结点；头结点算第 0 个
    int j = 0;

// 走 i-1 步，让 p 停在"第 i 个结点的前驱"上
// 循环条件 j < i - 1：i = 1 时一次也不进循环，p 直接就是头结点
    while (p != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 合法性检查：p 为空说明 i-1 已经超过表长；j > i-1 说明 i < 1
// 先检查后造结点，避免产生孤儿结点
    if (p == NULL || j > i - 1) return ERROR;

// 造新结点
    s = creatNode(e);

// ① 新结点的 next 接住后面的那一串
    s->next = p->next;
// ② 后面那个结点的 prior 改指新结点（表尾时 p->next 为空，必须判空）
    if (p->next != NULL)
    {
        p->next->prior = s;
    }
// ③ 新结点的 prior 指向前驱（前驱一定存在，不用判空）
// 前驱要么是头结点，要么是真实结点，绝不会是 NULL —— 这正是头结点的价值
    s->prior = p;
// ④ 前驱的 next 指向新结点，链表正式接上
    p->next = s;

// 返回 OK 表示插入成功
    return OK;
}

// ============ 这里体现双向链表真正的价值 ============
// 单链表要删除第 i 个结点，必须先找到第 i-1 个结点（前驱），
// 因为只有前驱能改 next 把待删结点绕过去：
//
//     单链表：  走 i-1 步找到前驱 p  →  改 p 一根指针  →  free
//
// 双向链表的第 i 个结点自己就带着 prior，压根不需要那个前驱变量：
//
//     双向链表：走 i 步定位到待删结点 p  →  用 p->prior 直接改两根指针  →  free
//
// 少了一次"找前驱"的过程，代码也更直白：删谁就站在谁身上操作。
//
// ============ 为什么 p->prior 不用判空 ============
// 因为 p 是第 i 个数据结点（i ≥ 1），它的前驱**至少是头结点**，
// 永远不可能是 NULL。头结点在这里又一次当了哨兵。
// 而 p->next 有可能是 NULL（删的正好是尾结点），所以那一句要判空。
//
// ============ 两根指针 + 一次 free ============
// 目标：删除第 2 个结点（值为 15）
//
//  删除前：  L ─▶ [头] ⇄ [10] ⇄ [15] ⇄ [20] ⇄ [30]
//                                p
//
//  ① p->prior->next = p->next
//          [10] ──▶ [20]            （[10] 的后继越过 [15]）
//
//  ② p->next->prior = p->prior
//          [20] ◀── [10]            （[20] 的前驱越过 [15]）
//
//  ③ free(p)
//          [15] 这块内存还给系统，p 变成野指针
//
//  删除后：  L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//
// 顺序要点：一定要先把 p->data 存进 *e，再 free(p)；
// free 之后再去读 p->data 就是"释放后使用"，属于未定义行为。

// 删除的数据要通过 *e 带出去
Status ListDelete(DuLinkList L, int i, ElemType *e)
{
// 注意：直接从第 1 个数据结点起步，目标是"第 i 个结点自己"
// 单链表这里必须从头结点起步去找前驱，双向链表不需要
    DuLNode *p = L->next;
// j 与 p 同步，表示 p 是第几个结点
    int j = 1;

// 走 i 步，让 p 停在待删结点上
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：p 为空说明第 i 个结点不存在
    if (p == NULL || j > i) return ERROR;

// 先把数据取出来交给调用者（必须在 free 之前做）
    *e = p->data;

// ① 前驱的后继越过 p
// p->prior 一定非空：它至少是头结点
    p->prior->next = p->next;
// ② 后继的前驱越过 p（删的是尾结点时 p->next 为空，必须判空）
    if (p->next != NULL)
    {
        p->next->prior = p->prior;
    }
// ③ 释放 p 占用的内存，防止内存泄漏
    free(p);

// 删除成功
    return OK;
}

// ============ 正向遍历：和单链表一模一样 ============
//
//   p = L->next;              ← 跳过不存数据的头结点
//   while (p != NULL) {       ← 走到 NULL 说明到尾了
//       ... 处理 p->data ...
//       p = p->next;          ← 千万别忘了这一句，否则死循环
//   }
//
// 输出用 `⇄` 而不是 `->`，是为了提醒这条链是**双向**的：
// 屏幕上看到的每个 `⇄`，在内存里都对应两根指针。
//
// 真正体现双向价值的是下一个模块 —— 反向打印。

// 只读操作，参数直接传 DuLinkList（一级指针）
void printList(DuLinkList L)
{
// 从第一个真实结点开始
    DuLNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，`⇄` 表示这里是双向连接
        printf("%d ⇄ ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}

// ============ 这就是双向链表多一个指针换来的能力 ============
// 单链表想倒着打印，只有两条路：
//   1. 递归（函数调用栈替你记住来路，但表长了会爆栈）；
//   2. 先把数据全拷进数组，再倒着输出（额外 O(n) 空间）。
// 双向链表不用这么麻烦 —— prior 就在结点里，直接往回走。
//
// ============ 为什么循环条件是 p != L 而不是 p != NULL ============
// 这是本模块最容易写错的地方。
//
//   反向走的时候，如果写 while (p != NULL)：
//     p 会一路走过头结点，而头结点的 data 是**没意义的垃圾值**，
//     屏幕上会莫名其妙多打一个数；再往后 p 变成 NULL 才停。
//
//   正确写法是 while (p != L)：
//     走到头结点就停 —— 头结点是哨兵，不该被当成数据打印。
//
// 顺带一提：正因为头结点的 prior 是 NULL，如果哪一步把"停"的条件写错，
// 就会顺着 NULL 继续取 prior，直接崩掉。
//
// ============ 走法示意 ============
//
//  第一步：顺着 next 找到尾结点
//    L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//                                  p
//
//  第二步：顺着 prior 一路往回，边走边打印，直到撞上头结点
//    L ─▶ [头] ⇄ [10] ⇄ [20] ⇄ [30]
//            p ◀──── 返回路径
//
//  屏幕上得到：  30 ⇄ 20 ⇄ 10 ⇄ NULL

// 只读操作，不需要修改链表
void printListReverse(DuLinkList L)
{
// 从头结点后面开始
    DuLNode *p = L->next;

// 空表同样单独处理
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回
        return;
    }

// 第一步：顺着 next 走到尾结点
// 条件写 p->next != NULL，所以停下时 p 正好是最后一个结点
    while (p->next != NULL)
    {
// 指针后移
        p = p->next;
    }

// 第二步：顺着 prior 往回走，撞到头结点就停
// 这里必须写 p != L，不能写 p != NULL —— 头结点不能被当成数据打印
    while (p != L)
    {
// 打印当前数据
        printf("%d ⇄ ", p->data);
// 顺着 prior 往回走一格（单链表没有这一步可走）
        p = p->prior;
    }

// 收尾
    printf("NULL\n");
}

// ============ 释放只需要 next 方向 ============
// 虽然结点里有 prior，但释放时**根本用不到它** ——
// 因为必须先把整条链走完才能全部释放，而"走完"只需要 next。
//
// ============ 为什么必须先保存 next ============
//
//  错误写法：                正确写法：
//    free(p);                  q = p;
//    p = p->next;   ← 危险!    p = p->next;
//                             free(q);
//
// free(p) 之后那块内存已经还给系统，p->next 读到的是垃圾值，
// 用这个垃圾值当地址去访问就是"释放后使用"（use after free）。
//
// 更危险的是：如果在 free(p) 之前先去动 p->prior->next 之类的指针
// （双向链表很容易顺手这么写），会把已经损坏的链再改一次，
// 崩溃点离真正的错误点非常远，极难排查。

// 参数是 DuLinkList *，因为最后要把调用者的 L 改成 NULL
void freeList(DuLinkList *L)
{
// 从第一个真实结点开始清理
    DuLNode *p = (*L)->next;
// q 用来暂存"即将被释放"的那个结点
    DuLNode *q = NULL;

// 逐个结点释放
    while (p != NULL)
    {
// 先记住当前结点
        q = p;
// 再让 p 走到下一个（此时 p 已经安全了）
        p = p->next;
// 最后才释放 q
// 这三步顺序固定：存 → 走 → 放，缺一不可
        free(q);
    }

// 数据结点都清完了，头结点也要还回去
    free(*L);
// 把调用者的指针置 NULL，避免它继续指向已释放的内存
    *L = NULL;
}

// ============ 双向链表的测试要多做一件事 ============
// 单链表只要正向打印对，基本就对了。
// 双向链表**每一步都要正反向打印对照** —— 因为漏改 prior 的 bug
// 正向完全看不出来，只有反向遍历（或后续的删除）才会暴露。
//
// 所以本测试里每次改动链表之后，都会同时打印正向和反向，
// 两个方向互为对方的"校验和"。
//
// 另外一定要测三种边界：
//   1. 空表      （初始化后立刻打印）
//   2. 越界位置  （插入/查找/修改/删除一个不存在的位置，应返回 ERROR）
//   3. 删尾结点  （专门验证 p->next == NULL 那条判空分支）

// 主函数不需要参数，返回 0 表示正常结束
int main(void)
{
// L 是头结点指针，先置 NULL，等 InitList 去创建头结点
    DuLinkList L = NULL;
// p 用来接 LocateElem 返回的结点地址
    DuLNode *p = NULL;
// e 用来接按位查找 / 删除带回来的数据
    ElemType e = 0;

// ========== 第 1 步：初始化 ==========
    printf("========== 1. 初始化 ==========\n");
// 检查返回值，初始化失败就没必要继续了
    if (InitList(&L) != OK)
    {
// 失败提示
        printf("初始化失败！\n");
// 直接返回错误码
        return ERROR;
    }
// 打印验证：此时应该是空表
    printf("初始化完成，当前链表：");
    printList(L);

// ========== 第 2 步：尾部追加 ==========
    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
// 依次追加三个数
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
// 期望正向：10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("追加后（正向）：");
    printList(L);
// 期望反向：30 ⇄ 20 ⇄ 10 ⇄ NULL
// 反向能打对，说明尾插时 s->prior = p 那一句没漏
    printf("追加后（反向）：");
    printListReverse(L);

// ========== 第 3 步：头插法 ==========
    printf("\n========== 3. 头插法插入 5 ==========\n");
// 头插 5：不遍历，直接变成第 1 个结点
    HeadInsert(L, 5);
// 期望正向：5 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("头插 5 后（正向）：");
    printList(L);
// 反向也要对：30 ⇄ 20 ⇄ 10 ⇄ 5 ⇄ NULL
    printf("头插 5 后（反向）：");
    printListReverse(L);

// ========== 第 4 步：按位插入 ==========
    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
// 插到第 2 个位置，即 5 和 10 之间
    ListInsert(L, 2, 15);
// 期望正向：5 ⇄ 15 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("插入后（正向）：");
    printList(L);
// 反向核对：30 ⇄ 20 ⇄ 10 ⇄ 15 ⇄ 5 ⇄ NULL
    printf("插入后（反向）：");
    printListReverse(L);

// 越界测试：在第 99 位插入必须失败
    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 5 步：按位查找 ==========
    printf("\n========== 5. 按位查找 ==========\n");
// 查第 3 个元素，用 e 带回结果
// 此时链表是 5 ⇄ 15 ⇄ 10 ⇄ 20 ⇄ 30，第 3 个是 10
    if (GetElem_L(L, 3, &e) == OK)
    {
// 期望输出：10
        printf("第 3 个元素的值是 %d\n", e);
    }
// 越界查找测试
    if (GetElem_L(L, 100, &e) == ERROR)
    {
// 期望走到这里
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

// ========== 第 6 步：按值查找 ==========
    printf("\n========== 6. 按值查找 ==========\n");
// 找值为 20 的结点
    p = LocateElem(L, 20);
// 找到就同时验证前后两个方向
    if (p != NULL)
    {
// 双向链表的好处：拿到结点就能同时说出它的前驱和后继
        printf("找到 20：它的前驱是 %d，后继是 %s\n",
               p->prior->data,
               p->next != NULL ? "一个有效结点" : "NULL");
    }
// 找不存在的值应当返回 NULL
    if (LocateElem(L, 99) == NULL)
    {
// 期望走到这里
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

// ========== 第 7 步：按位修改 ==========
    printf("\n========== 7. 按位修改 ==========\n");
// 把第 1 个元素改成 99
    if (ModifyElem(L, 1, 99) == OK)
    {
// 期望正向：99 ⇄ 15 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
        printf("把第 1 个元素改成 99 后：");
        printList(L);
    }
// 越界修改测试
    printf("改第 100 个元素：%s\n", ModifyElem(L, 100, 1) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 8 步：正反向遍历对照 ==========
    printf("\n========== 8. 正反向遍历对照 ==========\n");
// 同一份链表，两个方向必须互为倒序
    printf("正向：");
    printList(L);
    printf("反向：");
    printListReverse(L);

// ========== 第 9 步：按位删除 ==========
    printf("\n========== 9. 删除第 2 个结点 ==========\n");
// 删除第 2 个结点（值为 15），被删的值通过 e 带出来
    if (ListDelete(L, 2, &e) == OK)
    {
// 期望输出：被删除的是 15
        printf("已删除第 2 个结点，它的值是 %d\n", e);
    }
// 期望正向：99 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("删除后（正向）：");
    printList(L);
// 反向核对：30 ⇄ 20 ⇄ 10 ⇄ 99 ⇄ NULL
    printf("删除后（反向）：");
    printListReverse(L);

// 越界删除测试
    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 10 步：删尾结点（专测判空分支）==========
    printf("\n========== 10. 删除尾结点 ==========\n");
// 此时链表是 99 ⇄ 10 ⇄ 20 ⇄ 30，共 4 个结点
// 删尾结点会走到 p->next == NULL 那条分支 —— 也就是不执行"后继的 prior 改指"。
// 这条分支不测，删尾结点时的崩溃就永远不会被发现。
    if (ListDelete(L, 4, &e) == OK)
    {
        printf("已删除尾结点，它的值是 %d\n", e);
    }
// 期望正向：99 ⇄ 10 ⇄ 20 ⇄ NULL
    printf("删除尾结点后（正向）：");
    printList(L);
// 反向核对：20 ⇄ 10 ⇄ 99 ⇄ NULL
    printf("删除尾结点后（反向）：");
    printListReverse(L);

// ========== 第 11 步：释放整表 ==========
    printf("\n========== 11. 释放内存 ==========\n");
// 释放所有结点，并把 L 置为 NULL
    freeList(&L);
// 期望输出：NULL，证明 L 已被正确置空
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

// 正常结束
    return 0;
}

modes.short:
// 标准输入输出，printf 需要
#include <stdio.h>
// 内存管理，malloc / free 需要
#include <stdlib.h>

// 用宏定义状态码，让函数返回值有意义（比裸 1 / 0 好读）
#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

// Status 是函数返回类型；ElemType 是数据域类型
typedef int Status;
typedef int ElemType;

// 双向结点：数据域 + 前驱指针 + 后继指针
typedef struct DuLNode {
// 数据域，存具体元素
    ElemType data;
// 前驱指针：指向上一个结点（这是单链表没有的）
    struct DuLNode *prior;
// 后继指针：指向下一个结点，尾结点为 NULL
    struct DuLNode *next;
// 一次 typedef 出两个名字：DuLNode（结点）和 DuLinkList（指向结点的指针）
} DuLNode, *DuLinkList;


// 返回新结点的地址，所以返回类型是 DuLNode *
DuLNode *creatNode(ElemType e)
{
// 申请一个结点大小的内存，强制转换成 DuLNode *
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

// 申请失败必须拦住，否则后面 p->data 就是非法访问
    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
// 申请不到内存属于致命错误，直接结束程序
        exit(OVERFLOW);
    }

// 填数据域
    p->data = e;
// 前驱置 NULL（单链表没有这一步）
    p->prior = NULL;
// 后继置 NULL
    p->next = NULL;

// 把新结点的地址返回给调用者
    return p;
}


// 参数是 DuLinkList *（二级指针），因为要修改调用者手里的 L 本身
Status InitList(DuLinkList *L)
{
// 只申请头结点，不存数据
    *L = (DuLinkList)malloc(sizeof(DuLNode));
// 头结点也可能申请失败
    if (*L == NULL) return ERROR;
// 头结点的 prior 恒为 NULL，写出来是为了明确这条不变式
    (*L)->prior = NULL;
// 空表的标志：头结点的 next 为 NULL
    (*L)->next = NULL;
// 返回 OK 表示初始化成功
    return OK;
}


// 参数 L 是头结点指针，不需要改 L 本身，所以不用二级指针
Status applist(DuLinkList L, ElemType e)
{
// p 是"游标"，从头结点开始；它最终会停在尾结点上
    DuLNode *p = L;
// s 用来接住 creatNode 造出来的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过，直接报错
    if (L == NULL) return ERROR;

// 一路向后走，直到 p 后面没有结点了
    while (p->next != NULL)
    {
// 指针后移一格
        p = p->next;
    }

// 造新结点（此时它的 prior 和 next 都是 NULL）
    s = creatNode(e);

// 第一步：新结点的 prior 回指旧的尾结点
    s->prior = p;
// 第二步：旧尾结点的 next 指向新结点
    p->next = s;

// 返回 OK 表示追加成功
    return OK;
}


// 参数 L 是头结点指针，不需要改 L 本身
Status HeadInsert(DuLinkList L, ElemType e)
{
// s 是等待挂链的新结点
    DuLNode *s = NULL;

// 防御：L 为空说明没初始化过
    if (L == NULL) return ERROR;

// 造新结点
    s = creatNode(e);

// 第一步：新结点的 next 接住原来头结点后面的那一串
    s->next = L->next;
// 第二步：如果后面确实有结点，让它的 prior 改指新结点
    if (s->next != NULL)
    {
        s->next->prior = s;
    }
// 第三步：新结点的 prior 指向头结点
    s->prior = L;
// 第四步：头结点指向新结点，s 正式成为第 1 个结点
    L->next = s;

// 插入成功
    return OK;
}


// 结果通过 e 带回去，所以要传 ElemType *（地址），不是 ElemType
Status GetElem_L(DuLinkList L, int i, ElemType *e)
{
// 从第 1 个"带数据的结点"开始，所以是 L->next 而不是 L
    DuLNode *p = L->next;
// 计数器 j 与 p 同步，表示"p 现在指的是第几个结点"
    int j = 1;

// 边走边数，直到数到 i 或者走到表尾
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步加一
        j++;
    }

// 越界检查：p 为空说明 i 超过表长；j > i 说明 i 小于 1
    if (p == NULL || j > i) return ERROR;

// 把找到的数据写到调用者提供的地址里
    *e = p->data;

// 查找成功
    return OK;
}


// 返回 DuLNode *，找不到就是 NULL
DuLNode *LocateElem(DuLinkList L, ElemType e)
{
// 同样从第一个带数据的结点开始
    DuLNode *p = L->next;

// 两个条件：还没走到尾，且当前值不等于目标
    while (p != NULL && p->data != e)
    {
// 不匹配就继续往后
        p = p->next;
    }

// 找到返回地址，没找到时 p 已经是 NULL，直接返回即可
    return p;
}


// 要改的目标值通过 e 传进来（按值传递就够了，不需要指针）
Status ModifyElem(DuLinkList L, int i, ElemType e)
{
// 从第 1 个"带数据的结点"开始
    DuLNode *p = L->next;
// 计数器 j 与 p 同步
    int j = 1;

// 定位到第 i 个结点（与 GetElem_L 的循环完全相同）
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：第 i 个结点不存在就报错
    if (p == NULL || j > i) return ERROR;

// 把新值写进数据域 —— 只改数据，不碰任何指针
    p->data = e;

// 修改成功
    return OK;
}


// 参数 L 是头结点指针；i 是位置，e 是数据
Status ListInsert(DuLinkList L, int i, ElemType e)
{
// p 要从头结点开始：因为插到第 1 位时，前驱就是头结点
    DuLNode *p = L;
// s 是等待挂链的新结点
    DuLNode *s = NULL;
// j 表示 p 当前指向第几个结点；头结点算第 0 个
    int j = 0;

// 走 i-1 步，让 p 停在"第 i 个结点的前驱"上
    while (p != NULL && j < i - 1)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 合法性检查：p 为空说明 i-1 已经超过表长；j > i-1 说明 i < 1
    if (p == NULL || j > i - 1) return ERROR;

// 造新结点
    s = creatNode(e);

// ① 新结点的 next 接住后面的那一串
    s->next = p->next;
// ② 后面那个结点的 prior 改指新结点（表尾时 p->next 为空，必须判空）
    if (p->next != NULL)
    {
        p->next->prior = s;
    }
// ③ 新结点的 prior 指向前驱（前驱一定存在，不用判空）
    s->prior = p;
// ④ 前驱的 next 指向新结点，链表正式接上
    p->next = s;

// 返回 OK 表示插入成功
    return OK;
}


// 删除的数据要通过 *e 带出去
Status ListDelete(DuLinkList L, int i, ElemType *e)
{
// 注意：直接从第 1 个数据结点起步，目标是"第 i 个结点自己"
    DuLNode *p = L->next;
// j 与 p 同步，表示 p 是第几个结点
    int j = 1;

// 走 i 步，让 p 停在待删结点上
    while (p != NULL && j < i)
    {
// 指针后移
        p = p->next;
// 计数器同步
        j++;
    }

// 越界检查：p 为空说明第 i 个结点不存在
    if (p == NULL || j > i) return ERROR;

// 先把数据取出来交给调用者（必须在 free 之前做）
    *e = p->data;

// ① 前驱的后继越过 p
    p->prior->next = p->next;
// ② 后继的前驱越过 p（删的是尾结点时 p->next 为空，必须判空）
    if (p->next != NULL)
    {
        p->next->prior = p->prior;
    }
// ③ 释放 p 占用的内存，防止内存泄漏
    free(p);

// 删除成功
    return OK;
}


// 只读操作，参数直接传 DuLinkList（一级指针）
void printList(DuLinkList L)
{
// 从第一个真实结点开始
    DuLNode *p = L->next;

// 空表单独处理，提示比"什么都不打印"清楚得多
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回，不再进入循环
        return;
    }

// 标准遍历
    while (p != NULL)
    {
// 打印当前数据，`⇄` 表示这里是双向连接
        printf("%d ⇄ ", p->data);
// 推进到下一个结点
        p = p->next;
    }

// 收尾打印 NULL，标明链表末端
    printf("NULL\n");
}


// 只读操作，不需要修改链表
void printListReverse(DuLinkList L)
{
// 从头结点后面开始
    DuLNode *p = L->next;

// 空表同样单独处理
    if (p == NULL)
    {
// 空表提示
        printf("(空表)\n");
// 直接返回
        return;
    }

// 第一步：顺着 next 走到尾结点
    while (p->next != NULL)
    {
// 指针后移
        p = p->next;
    }

// 第二步：顺着 prior 往回走，撞到头结点就停
    while (p != L)
    {
// 打印当前数据
        printf("%d ⇄ ", p->data);
// 顺着 prior 往回走一格（单链表没有这一步可走）
        p = p->prior;
    }

// 收尾
    printf("NULL\n");
}


// 参数是 DuLinkList *，因为最后要把调用者的 L 改成 NULL
void freeList(DuLinkList *L)
{
// 从第一个真实结点开始清理
    DuLNode *p = (*L)->next;
// q 用来暂存"即将被释放"的那个结点
    DuLNode *q = NULL;

// 逐个结点释放
    while (p != NULL)
    {
// 先记住当前结点
        q = p;
// 再让 p 走到下一个（此时 p 已经安全了）
        p = p->next;
// 最后才释放 q
        free(q);
    }

// 数据结点都清完了，头结点也要还回去
    free(*L);
// 把调用者的指针置 NULL，避免它继续指向已释放的内存
    *L = NULL;
}


// 主函数不需要参数，返回 0 表示正常结束
int main(void)
{
// L 是头结点指针，先置 NULL，等 InitList 去创建头结点
    DuLinkList L = NULL;
// p 用来接 LocateElem 返回的结点地址
    DuLNode *p = NULL;
// e 用来接按位查找 / 删除带回来的数据
    ElemType e = 0;

// ========== 第 1 步：初始化 ==========
    printf("========== 1. 初始化 ==========\n");
// 检查返回值，初始化失败就没必要继续了
    if (InitList(&L) != OK)
    {
// 失败提示
        printf("初始化失败！\n");
// 直接返回错误码
        return ERROR;
    }
// 打印验证：此时应该是空表
    printf("初始化完成，当前链表：");
    printList(L);

// ========== 第 2 步：尾部追加 ==========
    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
// 依次追加三个数
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
// 期望正向：10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("追加后（正向）：");
    printList(L);
// 期望反向：30 ⇄ 20 ⇄ 10 ⇄ NULL
    printf("追加后（反向）：");
    printListReverse(L);

// ========== 第 3 步：头插法 ==========
    printf("\n========== 3. 头插法插入 5 ==========\n");
// 头插 5：不遍历，直接变成第 1 个结点
    HeadInsert(L, 5);
// 期望正向：5 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("头插 5 后（正向）：");
    printList(L);
// 反向也要对：30 ⇄ 20 ⇄ 10 ⇄ 5 ⇄ NULL
    printf("头插 5 后（反向）：");
    printListReverse(L);

// ========== 第 4 步：按位插入 ==========
    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
// 插到第 2 个位置，即 5 和 10 之间
    ListInsert(L, 2, 15);
// 期望正向：5 ⇄ 15 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("插入后（正向）：");
    printList(L);
// 反向核对：30 ⇄ 20 ⇄ 10 ⇄ 15 ⇄ 5 ⇄ NULL
    printf("插入后（反向）：");
    printListReverse(L);

// 越界测试：在第 99 位插入必须失败
    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 5 步：按位查找 ==========
    printf("\n========== 5. 按位查找 ==========\n");
// 查第 3 个元素，用 e 带回结果
    if (GetElem_L(L, 3, &e) == OK)
    {
// 期望输出：10
        printf("第 3 个元素的值是 %d\n", e);
    }
// 越界查找测试
    if (GetElem_L(L, 100, &e) == ERROR)
    {
// 期望走到这里
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

// ========== 第 6 步：按值查找 ==========
    printf("\n========== 6. 按值查找 ==========\n");
// 找值为 20 的结点
    p = LocateElem(L, 20);
// 找到就同时验证前后两个方向
    if (p != NULL)
    {
// 双向链表的好处：拿到结点就能同时说出它的前驱和后继
        printf("找到 20：它的前驱是 %d，后继是 %s\n",
               p->prior->data,
               p->next != NULL ? "一个有效结点" : "NULL");
    }
// 找不存在的值应当返回 NULL
    if (LocateElem(L, 99) == NULL)
    {
// 期望走到这里
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

// ========== 第 7 步：按位修改 ==========
    printf("\n========== 7. 按位修改 ==========\n");
// 把第 1 个元素改成 99
    if (ModifyElem(L, 1, 99) == OK)
    {
// 期望正向：99 ⇄ 15 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
        printf("把第 1 个元素改成 99 后：");
        printList(L);
    }
// 越界修改测试
    printf("改第 100 个元素：%s\n", ModifyElem(L, 100, 1) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 8 步：正反向遍历对照 ==========
    printf("\n========== 8. 正反向遍历对照 ==========\n");
// 同一份链表，两个方向必须互为倒序
    printf("正向：");
    printList(L);
    printf("反向：");
    printListReverse(L);

// ========== 第 9 步：按位删除 ==========
    printf("\n========== 9. 删除第 2 个结点 ==========\n");
// 删除第 2 个结点（值为 15），被删的值通过 e 带出来
    if (ListDelete(L, 2, &e) == OK)
    {
// 期望输出：被删除的是 15
        printf("已删除第 2 个结点，它的值是 %d\n", e);
    }
// 期望正向：99 ⇄ 10 ⇄ 20 ⇄ 30 ⇄ NULL
    printf("删除后（正向）：");
    printList(L);
// 反向核对：30 ⇄ 20 ⇄ 10 ⇄ 99 ⇄ NULL
    printf("删除后（反向）：");
    printListReverse(L);

// 越界删除测试
    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

// ========== 第 10 步：删尾结点（专测判空分支）==========
    printf("\n========== 10. 删除尾结点 ==========\n");
// 此时链表是 99 ⇄ 10 ⇄ 20 ⇄ 30，共 4 个结点
    if (ListDelete(L, 4, &e) == OK)
    {
        printf("已删除尾结点，它的值是 %d\n", e);
    }
// 期望正向：99 ⇄ 10 ⇄ 20 ⇄ NULL
    printf("删除尾结点后（正向）：");
    printList(L);
// 反向核对：20 ⇄ 10 ⇄ 99 ⇄ NULL
    printf("删除尾结点后（反向）：");
    printListReverse(L);

// ========== 第 11 步：释放整表 ==========
    printf("\n========== 11. 释放内存 ==========\n");
// 释放所有结点，并把 L 置为 NULL
    freeList(&L);
// 期望输出：NULL，证明 L 已被正确置空
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

// 正常结束
    return 0;
}

