#include <stdio.h>
#include <stdlib.h>

#define OK 1
#define ERROR 0
#define TRUE 1
#define FALSE 0
#define OVERFLOW -2

typedef int Status;
typedef int ElemType;

typedef struct DuLNode {
    ElemType data;
    struct DuLNode *prior;
    struct DuLNode *next;
} DuLNode, *DuLinkList;


DuLNode *creatNode(ElemType e)
{
    DuLNode *p = (DuLNode *)malloc(sizeof(DuLNode));

    if (p == NULL)
    {
        printf("内存分配失败：无法创建新结点。\n");
        exit(OVERFLOW);
    }

    p->data = e;
    p->prior = NULL;
    p->next = NULL;

    return p;
}


Status InitList(DuLinkList *L)
{
    *L = (DuLinkList)malloc(sizeof(DuLNode));
    if (*L == NULL) return ERROR;
    (*L)->prior = NULL;
    (*L)->next = NULL;
    return OK;
}


Status applist(DuLinkList L, ElemType e)
{
    DuLNode *p = L;
    DuLNode *s = NULL;

    if (L == NULL) return ERROR;

    while (p->next != NULL)
    {
        p = p->next;
    }

    s = creatNode(e);

    s->prior = p;
    p->next = s;

    return OK;
}


Status HeadInsert(DuLinkList L, ElemType e)
{
    DuLNode *s = NULL;

    if (L == NULL) return ERROR;

    s = creatNode(e);

    s->next = L->next;
    if (s->next != NULL)
    {
        s->next->prior = s;
    }
    s->prior = L;
    L->next = s;

    return OK;
}


Status GetElem_L(DuLinkList L, int i, ElemType *e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    return OK;
}


DuLNode *LocateElem(DuLinkList L, ElemType e)
{
    DuLNode *p = L->next;

    while (p != NULL && p->data != e)
    {
        p = p->next;
    }

    return p;
}


Status ModifyElem(DuLinkList L, int i, ElemType e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    p->data = e;

    return OK;
}


Status ListInsert(DuLinkList L, int i, ElemType e)
{
    DuLNode *p = L;
    DuLNode *s = NULL;
    int j = 0;

    while (p != NULL && j < i - 1)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i - 1) return ERROR;

    s = creatNode(e);

    s->next = p->next;
    if (p->next != NULL)
    {
        p->next->prior = s;
    }
    s->prior = p;
    p->next = s;

    return OK;
}


Status ListDelete(DuLinkList L, int i, ElemType *e)
{
    DuLNode *p = L->next;
    int j = 1;

    while (p != NULL && j < i)
    {
        p = p->next;
        j++;
    }

    if (p == NULL || j > i) return ERROR;

    *e = p->data;

    p->prior->next = p->next;
    if (p->next != NULL)
    {
        p->next->prior = p->prior;
    }
    free(p);

    return OK;
}


void printList(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p != NULL)
    {
        printf("%d ⇄ ", p->data);
        p = p->next;
    }

    printf("NULL\n");
}


void printListReverse(DuLinkList L)
{
    DuLNode *p = L->next;

    if (p == NULL)
    {
        printf("(空表)\n");
        return;
    }

    while (p->next != NULL)
    {
        p = p->next;
    }

    while (p != L)
    {
        printf("%d ⇄ ", p->data);
        p = p->prior;
    }

    printf("NULL\n");
}


void freeList(DuLinkList *L)
{
    DuLNode *p = (*L)->next;
    DuLNode *q = NULL;

    while (p != NULL)
    {
        q = p;
        p = p->next;
        free(q);
    }

    free(*L);
    *L = NULL;
}


int main(void)
{
    DuLinkList L = NULL;
    DuLNode *p = NULL;
    ElemType e = 0;

    printf("========== 1. 初始化 ==========\n");
    if (InitList(&L) != OK)
    {
        printf("初始化失败！\n");
        return ERROR;
    }
    printf("初始化完成，当前链表：");
    printList(L);

    printf("\n========== 2. 尾部追加 10 20 30 ==========\n");
    applist(L, 10);
    applist(L, 20);
    applist(L, 30);
    printf("追加后（正向）：");
    printList(L);
    printf("追加后（反向）：");
    printListReverse(L);

    printf("\n========== 3. 头插法插入 5 ==========\n");
    HeadInsert(L, 5);
    printf("头插 5 后（正向）：");
    printList(L);
    printf("头插 5 后（反向）：");
    printListReverse(L);

    printf("\n========== 4. 在第 2 位插入 15 ==========\n");
    ListInsert(L, 2, 15);
    printf("插入后（正向）：");
    printList(L);
    printf("插入后（反向）：");
    printListReverse(L);

    printf("在第 99 位插入 5 ：%s\n", ListInsert(L, 99, 5) == OK ? "成功" : "失败（越界，符合预期）");

    printf("\n========== 5. 按位查找 ==========\n");
    if (GetElem_L(L, 3, &e) == OK)
    {
        printf("第 3 个元素的值是 %d\n", e);
    }
    if (GetElem_L(L, 100, &e) == ERROR)
    {
        printf("查第 100 个元素失败（越界，符合预期）\n");
    }

    printf("\n========== 6. 按值查找 ==========\n");
    p = LocateElem(L, 20);
    if (p != NULL)
    {
        printf("找到 20：它的前驱是 %d，后继是 %s\n",
               p->prior->data,
               p->next != NULL ? "一个有效结点" : "NULL");
    }
    if (LocateElem(L, 99) == NULL)
    {
        printf("查找值 99 返回 NULL（符合预期）\n");
    }

    printf("\n========== 7. 按位修改 ==========\n");
    if (ModifyElem(L, 1, 99) == OK)
    {
        printf("把第 1 个元素改成 99 后：");
        printList(L);
    }
    printf("改第 100 个元素：%s\n", ModifyElem(L, 100, 1) == OK ? "成功" : "失败（越界，符合预期）");

    printf("\n========== 8. 正反向遍历对照 ==========\n");
    printf("正向：");
    printList(L);
    printf("反向：");
    printListReverse(L);

    printf("\n========== 9. 删除第 2 个结点 ==========\n");
    if (ListDelete(L, 2, &e) == OK)
    {
        printf("已删除第 2 个结点，它的值是 %d\n", e);
    }
    printf("删除后（正向）：");
    printList(L);
    printf("删除后（反向）：");
    printListReverse(L);

    printf("删除第 10 个结点：%s\n", ListDelete(L, 10, &e) == OK ? "成功" : "失败（越界，符合预期）");

    printf("\n========== 10. 删除尾结点 ==========\n");
    if (ListDelete(L, 4, &e) == OK)
    {
        printf("已删除尾结点，它的值是 %d\n", e);
    }
    printf("删除尾结点后（正向）：");
    printList(L);
    printf("删除尾结点后（反向）：");
    printListReverse(L);

    printf("\n========== 11. 释放内存 ==========\n");
    freeList(&L);
    printf("释放完成，L = %s\n", L == NULL ? "NULL" : "非 NULL");

    return 0;
}
